-- 0005_seed_question_bank.sql: Complete Question Bank Seeds from Questions Catalog
-- Guarantees non-zero question_bank_count on fresh D1 and satisfies all cognitive matrices

INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_1', 'lop_7', 'nhan_biet', 'published', 'phonics', 'Choose the word whose underlined part is pronounced differently: c<u>oa</u>ch, c<u>a</u>re, d<u>e</u>cide, sc<u>a</u>red', '["A. coach","B. care","C. decide","D. scared"]', 'C', 'Đáp án C: chữ ''c'' trong ''decide'' phát âm là /s/, trong khi ''coach'', ''care'', ''scared'' đều phát âm là /k/.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_2', 'lop_7', 'thong_hieu', 'published', 'phonics', 'Choose the word whose underlined part is pronounced differently: r<u>ea</u>lize, r<u>ea</u>der, s<u>ea</u>son, ov<u>er</u>seas', '["A. realize","B. reader","C. season","D. overseas"]', 'A', 'Đáp án A: ''ea'' trong ''realize'' phát âm là nguyên âm đôi /ɪə/ (/ˈrɪəlaɪz/), còn ''reader'', ''season'', ''overseas'' đều phát âm là nguyên âm dài /iː/.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_3', 'lop_7', 'van_dung', 'published', 'phonics', 'Choose the word whose -ed pronounced differently: nak<u>ed</u>, intend<u>ed</u>, wretch<u>ed</u>, plough<u>ed</u>', '["A. naked","B. intended","C. wretched","D. ploughed"]', 'D', 'Đáp án D: ''ploughed'' phát âm đuôi -ed là /d/ (/plaʊd/). Các từ ''naked'' /ˈneɪkɪd/, ''intended'' /ɪnˈtendɪd/, ''wretched'' /ˈretʃɪd/ đều phát âm đuôi -ed là /ɪd/.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_4', 'lop_7', 'van_dung_cao', 'published', 'phonics', 'Choose the word whose stress pattern is different: telephone, directory, computer, appliance', '["A. telephone","B. directory","C. computer","D. appliance"]', 'A', 'Đáp án A: ''telephone'' có trọng âm rơi vào âm tiết 1 (TE-le-phone /ˈtelɪfəʊn/), ba từ còn lại đều có trọng âm rơi vào âm tiết 2: di-REC-tory, com-PU-ter, ap-PLI-ance.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_5', 'lop_7', 'nhan_biet', 'published', 'phonics', 'Choose the word whose stress pattern is different: affect, affirm, study, collapse', '["A. affect","B. affirm","C. study","D. collapse"]', 'C', 'Đáp án C: ''study'' là động từ 2 âm tiết có trọng âm rơi vào âm 1 (STU-dy /ˈstʌdi/). Ba từ còn lại đều có trọng âm rơi vào âm 2: af-FECT, af-FIRM, col-LAPSE.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_6', 'lop_7', 'thong_hieu', 'published', 'vocabulary', 'Wave energy is a source of ______ energy.', '["A. environment friendly","B. environmental friendly","C. environmentally friendly","D. environmentally friendliness"]', 'C', 'Đáp án C: Cụm tính từ ghép ''environmentally friendly'' (trạng từ + tính từ) có nghĩa là thân thiện với môi trường.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_7', 'lop_7', 'van_dung', 'published', 'vocabulary', 'Do you want to know how you can ______ healthy?', '["A. make","B. have","C. stay","D. create"]', 'C', 'Đáp án C: Cụm cố định ''stay healthy'' có nghĩa là giữ gìn sức khỏe / sống khỏe mạnh.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_8', 'lop_7', 'van_dung_cao', 'published', 'grammar', 'Linh often uses her headphones when listening to music ______ her parents don''t like loud noise.', '["A. so","B. but","C. because","D. and"]', 'C', 'Đáp án C: Mệnh đề sau chỉ nguyên nhân lý do (''her parents don''t like loud noise'') -> dùng liên từ ''because''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_9', 'lop_7', 'nhan_biet', 'published', 'vocabulary', '______, many teenagers say they don''t like football - one of the world''s most popular games.', '["A. Surprise","B. Surprising","C. Surprisingly","D. Surprised"]', 'C', 'Đáp án C: Dùng trạng từ đứng đầu câu trước dấu phẩy để bổ nghĩa cho cả câu (''Surprisingly'' = Thật đáng ngạc nhiên là).', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_10', 'lop_7', 'thong_hieu', 'published', 'vocabulary', 'You should pay more ______ in class to understand the lesson thoroughly.', '["A. part","B. care","C. notice","D. attention"]', 'D', 'Đáp án D: Cụm thành ngữ ''pay attention to'' có nghĩa là chú ý, tập trung.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_11', 'lop_7', 'van_dung', 'published', 'vocabulary', 'My mother worries who will ______ our house when we are away for our summer holidays.', '["A. see","B. take after","C. take care of","D. look at"]', 'C', 'Đáp án C: ''take care of'' = chăm sóc, trông nom nhà cửa khi đi vắng.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_12', 'lop_7', 'van_dung_cao', 'published', 'grammar', 'Wearing a band over the wrist allows players ______ safely.', '["A. playing","B. to play","C. play","D. plays"]', 'B', 'Đáp án B: Cấu trúc ''allow somebody TO V'' (cho phép ai làm gì) -> to play.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_13', 'lop_7', 'nhan_biet', 'published', 'vocabulary', 'In my opinion, nuclear power is not only expensive but also ______ to our living environment.', '["A. danger","B. dangerous","C. risk","D. disaster"]', 'B', 'Đáp án B: Sau ''be'' và song hành với tính từ ''expensive'' trong cấu trúc ''not only... but also...'', ta cần tính từ ''dangerous''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_14', 'lop_7', 'thong_hieu', 'published', 'vocabulary', 'It''s considered very rude to ______ poorer people in the community.', '["A. look up to","B. look after","C. look down on","D. look for"]', 'C', 'Đáp án C: Cụm động từ ''look down on'' có nghĩa là coi thường, khinh miệt.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_15', 'lop_7', 'van_dung', 'published', 'grammar', '______ extremely tired after the long journey, I went straight to bed last night.', '["A. Felt","B. Feeling","C. To feel","D. Feel"]', 'B', 'Đáp án B: Mệnh đề phân từ hiện tại (Present Participle Clause ''Feeling'') rút gọn từ ''Because I felt extremely tired...''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_16', 'lop_7', 'van_dung_cao', 'published', 'grammar', '______ is the hottest planet in the solar system with surface temperatures exceeding 460°C.', '["A. Mercury","B. Venus","C. Mars","D. Uranus"]', 'B', 'Đáp án B: Sao Kim (Venus) là hành tinh nóng nhất trong hệ mặt trời do hiệu ứng nhà kính dày đặc từ khí CO2.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_17', 'lop_7', 'nhan_biet', 'published', 'grammar', 'The younger you are, ______ it is to acquire natural native-like pronunciation.', '["A. easier","B. the easier","C. easily","D. the easily"]', 'B', 'Đáp án B: Cấu trúc so sánh kép (The + comparative, the + comparative) -> the easier.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_18', 'lop_3', 'thong_hieu', 'published', 'reading', 'Let''s go to the ______ to read interesting fairy tales.', '["A. library","B. classroom","C. gym","D. canteen"]', 'A', 'Đáp án A: ''library'' là thư viện, nơi học sinh đến để đọc sách truyện.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_19', 'lop_3', 'van_dung', 'published', 'vocabulary', 'I keep my pens, pencils and eraser neatly inside my ______.', '["A. pencil case","B. desk","C. chair","D. ruler"]', 'A', 'Đáp án A: ''pencil case'' là hộp đựng bút.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_20', 'lop_4', 'van_dung_cao', 'published', 'reading', 'What do you like doing in your free time? - I love ______ shuttlecock with my classmates.', '["A. play","B. playing","C. plays","D. played"]', 'B', 'Đáp án B: Sau động từ chỉ sở thích ''love/like'' ta dùng danh động từ V-ing -> playing.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_21', 'lop_5', 'nhan_biet', 'published', 'grammar', 'Where did you go last summer holiday? - We ______ Phu Quoc Island by plane.', '["A. visit","B. visited","C. visiting","D. visits"]', 'B', 'Đáp án B: Câu hỏi ở thì quá khứ đơn ''did you go'' -> câu trả lời dùng động từ quá khứ ''visited''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_22', 'lop_9', 'thong_hieu', 'published', 'phonics', 'Choose the word whose underlined part is pronounced differently: poll<u>u</u>tion, prod<u>u</u>ce, red<u>u</u>ce, comm<u>u</u>nity', '["A. pollution","B. produce","C. reduce","D. community"]', 'A', 'Đáp án A: chữ ''u'' trong ''pollution'' phát âm là /uː/, còn trong ''produce'' /juː/, ''reduce'' /juː/, ''community'' /juː/ đều có bán nguyên âm /j/.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_23', 'lop_9', 'van_dung', 'published', 'grammar', 'If teenagers ______ more about environmental protection, our cities would be much cleaner.', '["A. care","B. cared","C. had cared","D. will care"]', 'B', 'Đáp án B: Mệnh đề chính có ''would be'' (loại 2) -> Mệnh đề IF chia quá khứ đơn: cared.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_24', 'lop_9', 'van_dung_cao', 'published', 'grammar', '"I will submit my English presentation tomorrow morning," said Nga. Choose the correct reported sentence:', '["A. Nga said she will submit her English presentation tomorrow morning.","B. Nga said she would submit her English presentation the following morning.","C. Nga said she would submit my English presentation tomorrow morning.","D. Nga told she submitted her English presentation the following morning."]', 'B', 'Đáp án B: Lùi thì ''will'' thành ''would'', đổi đại từ ''my'' thành ''her'', đổi trạng từ ''tomorrow morning'' thành ''the following morning''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_25', 'lop_11', 'nhan_biet', 'published', 'vocabulary', 'The local city council built a car-free ______ zone to encourage walking and reduce urban emissions.', '["A. pedestrian","B. dweller","C. sensor","D. infrastructure"]', 'A', 'Đáp án A: ''pedestrian zone'' là khu phố đi bộ cấm các phương tiện cơ giới.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_26', 'lop_11', 'thong_hieu', 'published', 'grammar', 'Environmental scientists firmly ______ that renewable energy is vital for sustainable smart cities.', '["A. believe","B. are believing","C. was believing","D. have been believing"]', 'A', 'Đáp án A: ''believe'' là động từ trạng thái (stative verb), không được chia ở các thì tiếp diễn.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_27', 'lop_12', 'van_dung', 'published', 'grammar', 'Our computers crashed. This caused all the trouble. Choose the closest sentence in meaning:', '["A. That our computers crashed resulted from all the trouble.","B. Owing to all the trouble, our computers crashed.","C. The trouble all stemmed from our computers crashing.","D. Our computers crashing was really annoying."]', 'C', 'Đáp án C: Cụm ''stem from'' có nghĩa là ''bắt nguồn từ, xuất phát từ'' -> Rắc rối đều bắt nguồn từ việc máy tính bị sập.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_28', 'lop_12', 'van_dung_cao', 'published', 'grammar', 'Anna is Ken''s boss. His harsh criticism of her may have a bad effect on him. Choose the best sentence:', '["A. Ken''s criticism of Anna may be rooted in the fact that she is his boss.","B. Ken''s criticism of Anna may be a matter of concern to her now that she''s his boss.","C. Ken''s criticism of Anna may be put into effect because she''s his boss.","D. Ken''s criticism of Anna may rebound on him now that she''s his boss."]', 'D', 'Đáp án D: Thành ngữ ''rebound on somebody'' có nghĩa là phản tác dụng, gây hậu quả xấu ngược lại cho chính người đó.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_29', 'lop_12', 'nhan_biet', 'published', 'vocabulary', 'The professor''s lecture on quantum physics was completely out of my ______.', '["A. deep","B. depth","C. deeply","D. deepen"]', 'B', 'Đáp án B: Thành ngữ ''out of my depth'' có nghĩa là vượt quá tầm hiểu biết / năng lực của tôi.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_30', 'lop_12', 'thong_hieu', 'published', 'vocabulary', 'The firefighters fought valiantly until the forest blaze was completely ______.', '["A. put out","B. put off","C. put away","D. put up with"]', 'A', 'Đáp án A: ''put out'' có nghĩa là dập tắt (đám cháy, ngọn lửa). ''put off'' là hoãn lại.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_31', 'lop_7', 'van_dung', 'published', 'phonics', 'Find the word which has a different sound in the underlined part: w<u>a</u>sh, w<u>a</u>rm, w<u>a</u>ll, w<u>a</u>lk', '["A. wash","B. warm","C. wall","D. walk"]', 'A', 'Đáp án A: ''wash'' phát âm là /ɒ/ (hoặc /ɑː/ trong Anh-Mỹ), còn ''warm'', ''wall'', ''walk'' đều phát âm là nguyên âm dài /ɔː/.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_32', 'lop_7', 'van_dung_cao', 'published', 'phonics', 'Find the word which has a different sound in the underlined part: p<u>a</u>n, b<u>a</u>g, w<u>a</u>ter, <u>a</u>dd', '["A. pan","B. bag","C. water","D. add"]', 'C', 'Đáp án C: ''water'' phát âm là /ɔː/ (/ˈwɔːtər/), trong khi ''pan'', ''bag'', ''add'' đều phát âm là nguyên âm bẹt /æ/.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_33', 'lop_3', 'nhan_biet', 'published', 'vocabulary', 'Look and choose the correct word: This is my _______. I carry my books in it.', '[]', 'A', 'Đáp án A: ''school bag'' (cặp sách) dùng để đựng sách vở đến trường.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_34', 'lop_3', 'thong_hieu', 'published', 'phonics', 'Choose the word whose underlined part is pronounced differently: b<u>a</u>g, h<u>a</u>t, c<u>a</u>t, f<u>a</u>ther', '[]', 'D', 'Đáp án D: ''father'' phát âm âm /ɑː/ dài, trong khi ''bag'', ''hat'', ''cat'' đều phát âm âm /æ/ ngắn.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_35', 'lop_3', 'van_dung', 'published', 'vocabulary', 'Odd one out: Which word is NOT a school supply?', '[]', 'C', 'Đáp án C: ''bedroom'' (phòng ngủ) là phòng trong nhà, các từ còn lại là đồ dùng học tập.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_36', 'lop_4', 'van_dung_cao', 'published', 'vocabulary', 'What time is it? - It is seven _______ (7:15).', '[]', 'A', 'Đáp án A: 7:15 đọc là ''seven fifteen'' hoặc ''a quarter past seven''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_37', 'lop_4', 'nhan_biet', 'published', 'vocabulary', 'My father is a doctor. He works in a _______.', '[]', 'B', 'Đáp án B: Bác sĩ (doctor) làm việc ở bệnh viện (hospital).', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_38', 'lop_4', 'thong_hieu', 'published', 'grammar', 'Choose the correct question: - _______ do you have English? - I have it on Mondays and Wednesdays.', '[]', 'C', 'Đáp án C: Hỏi về thời gian học (on Mondays and Wednesdays) dùng từ để hỏi ''When''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_39', 'lop_5', 'van_dung', 'published', 'grammar', 'Where did you go last summer holiday? - I went to Ha Long Bay _______ train.', '[]', 'B', 'Đáp án B: Cụm từ chỉ phương tiện giao thông dùng giới từ ''by'' (by train, by car, by plane).', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_40', 'lop_5', 'van_dung_cao', 'published', 'grammar', 'How often do you do morning exercise? - I do it _______ a week, on Tuesdays and Thursdays.', '[]', 'B', 'Đáp án B: Hai lần một tuần dùng trạng từ ''twice a week''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_41', 'lop_7', 'nhan_biet', 'published', 'phonics', 'Choose the word whose underlined part is pronounced differently: c<u>oa</u>ch, c<u>a</u>re, d<u>e</u>cide, sc<u>a</u>red', '[]', 'C', 'Đáp án C: chữ ''c'' trong ''decide'' phát âm là /s/, còn trong ''coach'', ''care'', ''scared'' phát âm là /k/.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_42', 'lop_7', 'thong_hieu', 'published', 'phonics', 'Choose the word with stress placed differently from the others: perform, gather, review, attract', '[]', 'B', 'Đáp án B: ''gather'' /ˈɡæðər/ có trọng âm rơi vào âm tiết 1; các từ còn lại đều có trọng âm rơi vào âm tiết 2 (/pəˈfɔːm/, /rɪˈvjuː/, /əˈtrækt/).', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_43', 'lop_7', 'van_dung', 'published', 'vocabulary', 'The government is trying to encourage people to use _______ sources of energy such as wind and solar.', '[]', 'A', 'Đáp án A: ''renewable energy'' (năng lượng tái tạo) gồm năng lượng gió (wind) và mặt trời (solar).', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_44', 'lop_7', 'van_dung_cao', 'published', 'grammar', 'My mother used to _______ a small red bicycle when she was a student.', '[]', 'B', 'Đáp án B: Cấu trúc thói quen quá khứ: used to + V_nguyên thể (ride).', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_45', 'lop_7', 'nhan_biet', 'published', 'grammar', 'Choose the correct sentence transformation: ''She started learning English 5 years ago.''', '[]', 'A', 'Đáp án A: Chuyển đổi thì Quá khứ đơn ''started V-ing ... ago'' sang Hiện tại hoàn thành ''have/has V3/ed for ...''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_46', 'lop_12', 'thong_hieu', 'published', 'vocabulary', 'It is amazing how _______ she looks at her age! (YOUTH)', '[]', 'A', 'Đáp án A: Sau liên từ/động từ nối ''looks'' cần một tính từ miêu tả ngoại hình. ''youthful'' = trẻ trung, đầy sức sống.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_47', 'lop_12', 'van_dung', 'published', 'vocabulary', 'We had an exceedingly _______ day boating on the lake. (ENJOY)', '[]', 'A', 'Đáp án A: Trước danh từ ''day'' và sau phó từ ''exceedingly'' cần một tính từ mang nghĩa tích cực: ''enjoyable'' = thú vị, tràn ngập niềm vui.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_48', 'lop_12', 'van_dung_cao', 'published', 'vocabulary', 'Snow lasts considerably longer in _______ regions. (MOUNTAIN)', '[]', 'A', 'Đáp án A: ''mountainous regions'' = các vùng đồi núi hiểm trở.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_49', 'lop_12', 'nhan_biet', 'published', 'vocabulary', 'He proved so stubborn that it seemed completely _______ to insist. (POINT)', '[]', 'A', 'Đáp án A: ''pointless'' = vô ích, vô nghĩa. Sau linking verb ''seemed'' cần tính từ mang nghĩa nản lòng khi ai đó bướng bỉnh.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_50', 'lop_12', 'thong_hieu', 'published', 'vocabulary', 'Do you happen to know the exact _______ of Ben Nevis? (HIGH)', '[]', 'A', 'Đáp án A: Sau mạo từ ''the exact'' cần danh từ chỉ độ cao: ''height'' (từ gốc tính từ ''high'').', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_51', 'lop_11', 'van_dung', 'published', 'grammar', 'Scientists firmly _______ that green hydrogen will be the primary fuel of tomorrow.', '[]', 'A', 'Đáp án A: ''believe'' là động từ trạng thái (stative verb), không chia ở thì tiếp diễn.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_52', 'lop_11', 'van_dung_cao', 'published', 'grammar', 'Not until the late 20th century _______ the urgent need for eco-friendly urban zoning.', '[]', 'A', 'Đáp án A: Cấu trúc đảo ngữ với ''Not until + time/clause + trợ động từ (did) + S + V_inf''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_53', 'lop_12', 'nhan_biet', 'published', 'grammar', 'Mark the letter A, B, C, or D to indicate the best response to complete the dialogue:
- Nam: ''Would you mind turning down the radio? I am preparing for my graduation test.''
- Lan: ''_______''', '[]', 'A', 'Đáp án A: Khi được hỏi lịch sự ''Would you mind...?'' (Bạn có phiền không?), câu trả lời đồng ý giúp đỡ là ''Not at all'' (Không hề phiền).', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_54', 'lop_12', 'thong_hieu', 'published', 'vocabulary', 'The rapid expansion of artificial intelligence in healthcare has yielded _______ advancements in early tumor detection.', '[]', 'A', 'Đáp án A: ''unprecedented advancements'' = những tiến bộ chưa từng có tiền lệ.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_55', 'lop_12', 'van_dung', 'published', 'grammar', 'In academic writing, which cohesive device is best suited to introduce an opposing perspective?', '[]', 'A', 'Đáp án A: ''Conversely'' (ngược lại) dùng để đối chiếu một góc nhìn trái ngược hoàn toàn.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_56', 'lop_12', 'van_dung_cao', 'published', 'vocabulary', 'The proposed carbon tax policy was heavily criticized for imposing a _______ financial burden on marginalized households.', '[]', 'A', 'Đáp án A: ''disproportionate burden'' = gánh nặng mất cân đối, quá mức.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_57', 'lop_12', 'nhan_biet', 'published', 'grammar', 'The attending physician insisted that his patient ______ complete bed rest for at least two weeks.', '[]', 'A', 'Đáp án A: Cấu trúc thể giả định (subjunctive mood) với động từ ''insist that + S + (should) + V_nguyên thể'' không chia.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_58', 'lop_12', 'thong_hieu', 'published', 'grammar', 'Only in the most pristine and protected rainforest environments ______ these endangered orchid species flourish.', '[]', 'A', 'Đáp án A: Đảo ngữ với cụm từ mở đầu ''Only in...'': Trợ động từ ''can'' đứng ngay trước chủ ngữ ''these endangered orchid species''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_59', 'lop_12', 'van_dung', 'published', 'grammar', 'Hardly ______ the final whistle blown when celebratory fireworks erupted throughout the stadium.', '[]', 'A', 'Đáp án A: Cấu trúc đảo ngữ ''Hardly had + S + V3/ed + when + S + V2/ed'' diễn tả hành động vừa xảy ra thì hành động khác ập tới.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_60', 'lop_11', 'van_dung_cao', 'published', 'vocabulary', 'It was the third time in six months that the neighborhood jewelry store had been ______ by masked burglars.', '[]', 'A', 'Đáp án A: ''hold up'' mang nghĩa cướp có vũ trang (to rob someone or a bank/store using weapons).', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_61', 'lop_11', 'nhan_biet', 'published', 'vocabulary', 'The environmental summit organizers decided to ______ the outdoor opening ceremony due to gale-force winds.', '[]', 'A', 'Đáp án A: ''call off'' = hủy bỏ sự kiện (cancel).', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_62', 'lop_7', 'thong_hieu', 'published', 'vocabulary', 'We are sincerely looking forward to ______ from the scholarship admission board soon.', '[]', 'A', 'Đáp án A: Sau cấu trúc ''look forward to'' là danh động từ V-ing (''hearing'').', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_63', 'lop_9', 'van_dung', 'published', 'grammar', 'Rewrite: ''If the project is finished by lunchtime, you can leave early.'' -> ''Provided ______''', '[]', 'A', 'Đáp án A: ''Provided (that) + clause'' thay thế hoàn hảo cho liên từ điều kiện ''If + clause''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_64', 'lop_9', 'van_dung_cao', 'published', 'grammar', 'Rewrite: ''They last renovated their ancestral home five years ago.'' -> ''They haven''t ______''', '[]', 'A', 'Đáp án A: Chuyển đổi từ ''last V2/ed ... ago'' sang ''haven''t/hasn''t V3/ed for ...''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_65', 'lop_12', 'nhan_biet', 'published', 'vocabulary', 'The metropolitan city''s _______ suffered heavy collapse during the historic flooding.', '[]', 'A', 'Đáp án A: ''infrastructure'' = cơ sở hạ tầng (cầu cống, đường sá, lưới điện).', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_66', 'lop_12', 'thong_hieu', 'published', 'vocabulary', 'More green corridors and rooftop gardens must be planted to guarantee _______ urban expansion.', '[]', 'A', 'Đáp án A: ''sustainable urban expansion'' = sự phát triển/mở rộng đô thị bền vững.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_67', 'lop_12', 'van_dung', 'published', 'vocabulary', 'The ancient _______ of Thang Long preserves multi-layered relics from the Ly, Tran, and Le dynasties.', '[]', 'A', 'Đáp án A: ''citadel'' = thành lũy, hoàng thành cổ kính (Imperial Citadel of Thang Long).', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_68', 'lop_8', 'van_dung_cao', 'published', 'grammar', 'Rewrite the sentence: ''Because she behaves well, everybody loves her.'' -> Choose the correct rewrite:', '["A. Because of her good behaviour, everybody loves her.","B. Because of she behaves well, everybody loves her.","C. Because of behaving good, everybody loves her.","D. Because of her behavior is good, everybody loves her."]', 'A', 'Cấu trúc Model 1: Because + clause -> Because of + Noun phrase (''her good behaviour'').', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_69', 'lop_8', 'nhan_biet', 'published', 'vocabulary', 'It was the third time in six months that the bank had been held ______ by armed robbers.', '["A. over","B. down","C. up","D. out"]', 'C', 'Cụm động từ: Hold up sth = Cướp có vũ trang, chặn đường cướp bóc.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_70', 'lop_12', 'thong_hieu', 'published', 'grammar', 'John will start studying for the decisive exam ______.', '["A. after he finished his lunch","B. when he finishes his lunch","C. before he finished his lunch","D. until he is finishing his lunch"]', 'B', 'Quy tắc phối hợp thì: Tương lai đơn (will start) đi với liên từ thời gian ''when'' + Hiện tại đơn (finishes).', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_71', 'lop_12', 'van_dung', 'published', 'grammar', '______ on his fourth proposal did she finally accept to marry him.', '["A. Only","B. Hardly","C. Not until","D. No sooner"]', 'A', 'Cấu trúc đảo ngữ: Only on + Noun phrase + trợ động từ (did) + S + V-inf.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_72', 'lop_12', 'van_dung_cao', 'published', 'grammar', 'Find the error: ''The manager along with (A) his dedicated staff (B) are attending (C) the international summit in (D) Singapore.''', '["A. along with","B. are attending","C. international","D. in"]', 'B', 'Lỗi hòa hợp Chủ ngữ - Động từ: Chủ ngữ chính là ''The manager'' (số ít). ''along with his staff'' là trạng ngữ chêm. Sửa ''are attending'' thành ''is attending''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_73', 'lop_5', 'nhan_biet', 'published', 'phonics', 'Choose the word whose underlined part is pronounced differently: b<u>u</u>s, b<u>u</u>t, p<u>u</u>t, c<u>u</u>t', '["A. bus","B. but","C. put","D. cut"]', 'C', '''put'' phát âm là nguyên âm ngắn /ʊ/. Ba từ còn lại ''bus'', ''but'', ''cut'' đều phát âm là /ʌ/.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_74', 'lop_8', 'thong_hieu', 'published', 'grammar', 'Rewrite the sentence: ''Because she behaves well, everybody loves her.'' -> Choose the correct rewrite:', '["A. Because of her good behaviour, everybody loves her.","B. Because of she behaves well, everybody loves her.","C. Because of behaving good, everybody loves her.","D. Because of her behavior is good, everybody loves her."]', 'A', 'Cấu trúc Model 1: Because + clause -> Because of + Noun phrase (''her good behaviour'').', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_75', 'lop_8', 'van_dung', 'published', 'vocabulary', 'It was the third time in six months that the bank had been held ______ by armed robbers.', '["A. over","B. down","C. up","D. out"]', 'C', 'Cụm động từ: Hold up sth = Cướp có vũ trang, chặn đường cướp bóc.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_76', 'lop_12', 'van_dung_cao', 'published', 'grammar', 'John will start studying for the decisive exam ______.', '["A. after he finished his lunch","B. when he finishes his lunch","C. before he finished his lunch","D. until he is finishing his lunch"]', 'B', 'Quy tắc phối hợp thì: Tương lai đơn (will start) đi với liên từ thời gian ''when'' + Hiện tại đơn (finishes).', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_77', 'lop_12', 'nhan_biet', 'published', 'grammar', '______ on his fourth proposal did she finally accept to marry him.', '["A. Only","B. Hardly","C. Not until","D. No sooner"]', 'A', 'Cấu trúc đảo ngữ: Only on + Noun phrase + trợ động từ (did) + S + V-inf.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_78', 'lop_12', 'thong_hieu', 'published', 'grammar', 'Find the error: ''The manager along with (A) his dedicated staff (B) are attending (C) the international summit in (D) Singapore.''', '["A. along with","B. are attending","C. international","D. in"]', 'B', 'Lỗi hòa hợp Chủ ngữ - Động từ: Chủ ngữ chính là ''The manager'' (số ít). ''along with his staff'' là trạng ngữ chêm. Sửa ''are attending'' thành ''is attending''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_79', 'lop_5', 'van_dung', 'published', 'phonics', 'Choose the word whose underlined part is pronounced differently: b<u>u</u>s, b<u>u</u>t, p<u>u</u>t, c<u>u</u>t', '["A. bus","B. but","C. put","D. cut"]', 'C', '''put'' phát âm là nguyên âm ngắn /ʊ/. Ba từ còn lại ''bus'', ''but'', ''cut'' đều phát âm là /ʌ/.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_80', 'lop_8', 'van_dung_cao', 'published', 'grammar', 'Rewrite the sentence: ''Because she behaves well, everybody loves her.'' -> Choose the correct rewrite:', '["A. Because of her good behaviour, everybody loves her.","B. Because of she behaves well, everybody loves her.","C. Because of behaving good, everybody loves her.","D. Because of her behavior is good, everybody loves her."]', 'A', 'Cấu trúc Model 1: Because + clause -> Because of + Noun phrase (''her good behaviour'').', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_81', 'lop_8', 'nhan_biet', 'published', 'vocabulary', 'It was the third time in six months that the bank had been held ______ by armed robbers.', '["A. over","B. down","C. up","D. out"]', 'C', 'Cụm động từ: Hold up sth = Cướp có vũ trang, chặn đường cướp bóc.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_82', 'lop_12', 'thong_hieu', 'published', 'grammar', 'John will start studying for the decisive exam ______.', '["A. after he finished his lunch","B. when he finishes his lunch","C. before he finished his lunch","D. until he is finishing his lunch"]', 'B', 'Quy tắc phối hợp thì: Tương lai đơn (will start) đi với liên từ thời gian ''when'' + Hiện tại đơn (finishes).', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_83', 'lop_12', 'van_dung', 'published', 'grammar', '______ on his fourth proposal did she finally accept to marry him.', '["A. Only","B. Hardly","C. Not until","D. No sooner"]', 'A', 'Cấu trúc đảo ngữ: Only on + Noun phrase + trợ động từ (did) + S + V-inf.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_84', 'lop_12', 'van_dung_cao', 'published', 'grammar', 'Find the error: ''The manager along with (A) his dedicated staff (B) are attending (C) the international summit in (D) Singapore.''', '["A. along with","B. are attending","C. international","D. in"]', 'B', 'Lỗi hòa hợp Chủ ngữ - Động từ: Chủ ngữ chính là ''The manager'' (số ít). ''along with his staff'' là trạng ngữ chêm. Sửa ''are attending'' thành ''is attending''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_85', 'lop_5', 'nhan_biet', 'published', 'phonics', 'Choose the word whose underlined part is pronounced differently: b<u>u</u>s, b<u>u</u>t, p<u>u</u>t, c<u>u</u>t', '["A. bus","B. but","C. put","D. cut"]', 'C', '''put'' phát âm là nguyên âm ngắn /ʊ/. Ba từ còn lại ''bus'', ''but'', ''cut'' đều phát âm là /ʌ/.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_86', 'lop_9', 'thong_hieu', 'published', 'grammar', 'Choose the best rewrite: ''The weather was so severe that all flights were cancelled.''', '["A. Such was the severity of the weather that all flights were cancelled.","B. It was so severe weather that flights cancelled.","C. Severe as was the weather, flights were cancelled.","D. Due to weather severe, flights were cancelled."]', 'A', 'Cấu trúc đảo ngữ với SUCH: Such + be + Noun phrase + that + clause. ''Such was the severity of the weather...''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_87', 'lop_9', 'van_dung', 'published', 'grammar', '______ had the director stepped into the conference hall than the audience erupted in applause.', '["A. No sooner","B. Hardly","C. Scarcely","D. Only when"]', 'A', 'Cấu trúc: No sooner had + S + P.P + THAN... Chú ý từ nối ''than'' bắt buộc đi với No sooner.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_88', 'lop_9', 'van_dung_cao', 'published', 'grammar', 'It is imperative that every candidate ______ silent throughout the official examination.', '["A. remain","B. remains","C. remained","D. will remain"]', 'A', 'Thể giả định sau tính từ khẩn thiết ''imperative that + S + (should) + V-bare'' -> dùng động từ nguyên thể ''remain''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_89', 'lop_11', 'nhan_biet', 'published', 'vocabulary', 'The local municipality took urgent actions to ______ the severe flood damage in residential areas.', '["A. mitigate","B. exacerbate","C. deteriorate","D. contradict"]', 'A', 'Từ vựng học thuật (Harold Levine): Mitigate = làm giảm nhẹ, làm dịu bớt thiệt hại.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_90', 'lop_11', 'thong_hieu', 'published', 'vocabulary', 'Living in a dense metropolitan area often requires people to bridge the generation ______.', '["A. gap","B. space","C. distance","D. hole"]', 'A', 'Cụm danh từ cố định: ''generation gap'' = khoảng cách giữa các thế hệ.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_91', 'lop_11', 'van_dung', 'published', 'grammar', 'He ______ the winning lottery ticket; otherwise, he wouldn''t have looked so bewildered and joyous!', '["A. must have bought","B. shouldn''t have bought","C. can''t have bought","D. needn''t have bought"]', 'A', 'Suy đoán chắc chắn trong quá khứ có bằng chứng: Must have + P.P.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_92', 'lop_6', 'van_dung_cao', 'published', 'grammar', 'My brother usually ______ his homework right after dinner.', '["A. does","B. do","C. is doing","D. did"]', 'A', 'Thì hiện tại đơn diễn tả thói quen lặp đi lặp lại với ''usually'', chủ ngữ ngôi 3 số ít ''My brother'' đi với ''does''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_93', 'lop_6', 'nhan_biet', 'published', 'phonics', 'Which word has the underlined part pronounced as /z/? book<u>s</u>, map<u>s</u>, pen<u>s</u>, cat<u>s</u>', '["A. pens","B. books","C. maps","D. cats"]', 'A', 'Đuôi -s trong ''pens'' đứng sau âm hữu thanh /n/ nên phát âm là /z/. Ba từ còn lại tận cùng là âm vô thanh /k, p, t/ nên phát âm là /s/.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_94', 'lop_1', 'thong_hieu', 'published', 'phonics', 'Which word starts with the sound /b/? <u>b</u>all, <u>c</u>at, <u>a</u>pple, <u>d</u>og', '["A. ball","B. cat","C. apple","D. dog"]', 'A', 'Từ ''ball'' bắt đầu bằng âm phụ âm bật hữu thanh /b/.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_95', 'lop_2', 'van_dung', 'published', 'vocabulary', 'Choose the family member: Who is your mother''s mother?', '["A. Grandmother","B. Aunt","C. Sister","D. Cousin"]', 'A', 'Mẹ của mẹ là bà (Grandmother).', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_96', 'lop_10', 'van_dung_cao', 'published', 'grammar', '______ by the majestic scenery of Ha Long Bay, the tourists took hundreds of photos.', '["A. Mesmerized","B. Mesmerizing","C. Having mesmerized","D. To mesmerize"]', 'A', 'Rút gọn mệnh đề phân từ dạng bị động: P.P (Mesmerized by...) = Bị hớp hồn bởi cảnh sắc hùng vĩ.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_97', 'lop_10', 'nhan_biet', 'published', 'grammar', 'Find the error: ''Neither the teacher (A) nor her students (B) was present (C) at the science symposium (D) yesterday.''', '["A. nor","B. her students","C. was present","D. at"]', 'C', 'Hòa hợp với Neither... nor: Động từ chia theo chủ ngữ gần nó nhất. ''her students'' là số nhiều -> Sửa ''was present'' thành ''were present''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_98', 'lop_9', 'thong_hieu', 'published', 'grammar', 'Rewrite the sentence: ''In spite of being tired, they stayed until they found out what happened.''', '["A. Although they were very tired, they stayed until they found out what happened.","B. Although they were tired, but they stayed until they found out what happened.","C. Despite they were tired, they stayed until they found out what happened.","D. Because they were tired, they stayed until they found out what happened."]', 'A', 'Model 2 trong chuyên đề Viết lại câu HSG: In spite of + V-ing -> Although + S + was/were + adj. Không dùng ''but'' sau although.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_99', 'lop_9', 'van_dung', 'published', 'grammar', 'Rewrite the sentence: ''Mary is too young to get married.''', '["A. Mary isn’t old enough to get married.","B. Mary isn''t enough old to get married.","C. Mary is so young that she can get married.","D. Mary is such young girl that she can''t get married."]', 'A', 'Model 4: S + be + too + adj + to-inf -> S + be not + adj (trái nghĩa) + enough + to-inf. Lưu ý vị trí ''old enough''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_100', 'lop_9', 'van_dung_cao', 'published', 'grammar', 'Rewrite the sentence: ''This question is easy enough for us to answer.''', '["A. It is such an easy question that we can answer it.","B. The question is too easy that we can answer.","C. It is so easy question that we can answer.","D. This question is such easy for us to answer."]', 'A', 'Model 5: Adj + enough for sb to V -> It is such a/an + adj + noun + that + S + can + V.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_101', 'lop_12', 'nhan_biet', 'published', 'grammar', 'Rewrite the sentence: ''He had no sooner started his car than the tire burst.''', '["A. Hardly had he started his car when the tire burst.","B. No sooner did he start his car when the tire burst.","C. Hardly had he started his car than the tire burst.","D. Barely had he started his car than the tire burst."]', 'A', 'Cấu trúc đảo ngữ tương đương: No sooner had... than... = Hardly had... when...', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_102', 'lop_12', 'thong_hieu', 'published', 'grammar', 'Rewrite the sentence: ''She hasn''t eaten sushi since she was in Tokyo three years ago.''', '["A. The last time she ate sushi was when she was in Tokyo three years ago.","B. She last eaten sushi three years ago in Tokyo.","C. It is three years since she hasn''t eaten sushi.","D. This is the first time she ate sushi in Tokyo."]', 'A', 'Biến đổi thì hiện tại hoàn thành phủ định: S + haven''t/hasn''t + P.P + since... -> The last time + S + V-ed + was...', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_103', 'lop_11', 'van_dung', 'published', 'grammar', 'Rewrite the sentence: ''It is said that the company lost millions of dollars during the crisis.''', '["A. The company is said to have lost millions of dollars during the crisis.","B. The company was said to lose millions of dollars during the crisis.","C. The company is said to lose millions of dollars during the crisis.","D. Millions of dollars are said to lost by the company."]', 'A', 'Bị động khách quan khác thì: Mệnh đề chính ở hiện tại (is said), mệnh đề phụ ở quá khứ (lost) -> dùng ''to have + P.P'' (to have lost).', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_104', 'lop_11', 'van_dung_cao', 'published', 'grammar', 'Rewrite: ''I''d rather you didn''t smoke in here.'' -> ''I would prefer ______.''', '["A. you not to smoke in here.","B. you didn''t smoke in here.","C. you not smoking in here.","D. you haven''t smoked in here."]', 'A', 'Prefer sb (not) to V = Would rather sb + V-ed. ''I would prefer you not to smoke in here''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_105', 'lop_8', 'nhan_biet', 'published', 'grammar', 'Rewrite: ''Shall we go to the museum this weekend?'' -> ''How about ______?''', '["A. going to the museum this weekend?","B. to go to the museum this weekend?","C. we go to the museum this weekend?","D. go to the museum this weekend?"]', 'A', 'Cấu trúc đề xuất gợi ý: Shall we + V-inf? = How about / What about + V-ing? = Let''s + V-inf.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_106', 'lop_11', 'thong_hieu', 'published', 'grammar', 'He was out of breath because he ______ for half an hour. (Biến thể 1)', '["A. had been running","B. was running","C. has run","D. ran"]', 'A', 'Nhấn mạnh quá trình chạy diễn ra liên tục gây nên hậu quả thở dốc.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_107', 'lop_11', 'van_dung', 'published', 'grammar', 'He was out of breath because he ______ for half an hour. (Biến thể 2)', '["A. had been running","B. was running","C. has run","D. ran"]', 'A', 'Nhấn mạnh quá trình chạy diễn ra liên tục gây nên hậu quả thở dốc.', NULL);
