INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_111', 'lop_12', 'van_dung', 'published', 'grammar', '______ by the loud explosion, everyone rushed out of the building. (Biến thể 1)', '["A. Terrified","B. Terrifying","C. Having terrified","D. To terrify"]', 'A', 'Mệnh đề phân từ quá khứ mang nghĩa bị động (Terrified by...).', NULL);
