INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_151', 'lop_11', 'van_dung', 'published', 'grammar', 'Under no circumstances ______ reveal your account password to strangers. (Biến thể 1)', '["A. should you","B. you should","C. you must","D. must you not"]', 'A', 'Đảo ngữ với Under no circumstances + should/must + S + V-inf.', NULL);
