INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_156', 'lop_9', 'van_dung_cao', 'published', 'grammar', 'Rewrite the sentence: ''In spite of being tired, they stayed until they found out what happened.''', '["A. Although they were very tired, they stayed until they found out what happened.","B. Although they were tired, but they stayed until they found out what happened.","C. Despite they were tired, they stayed until they found out what happened.","D. Because they were tired, they stayed until they found out what happened."]', 'A', 'Model 2 trong chuyên đề Viết lại câu HSG: In spite of + V-ing -> Although + S + was/were + adj. Không dùng ''but'' sau although.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_157', 'lop_9', 'nhan_biet', 'published', 'grammar', 'Rewrite the sentence: ''Mary is too young to get married.''', '["A. Mary isn’t old enough to get married.","B. Mary isn''t enough old to get married.","C. Mary is so young that she can get married.","D. Mary is such young girl that she can''t get married."]', 'A', 'Model 4: S + be + too + adj + to-inf -> S + be not + adj (trái nghĩa) + enough + to-inf. Lưu ý vị trí ''old enough''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_158', 'lop_9', 'thong_hieu', 'published', 'grammar', 'Rewrite the sentence: ''This question is easy enough for us to answer.''', '["A. It is such an easy question that we can answer it.","B. The question is too easy that we can answer.","C. It is so easy question that we can answer.","D. This question is such easy for us to answer."]', 'A', 'Model 5: Adj + enough for sb to V -> It is such a/an + adj + noun + that + S + can + V.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_159', 'lop_12', 'van_dung', 'published', 'grammar', 'Rewrite the sentence: ''He had no sooner started his car than the tire burst.''', '["A. Hardly had he started his car when the tire burst.","B. No sooner did he start his car when the tire burst.","C. Hardly had he started his car than the tire burst.","D. Barely had he started his car than the tire burst."]', 'A', 'Cấu trúc đảo ngữ tương đương: No sooner had... than... = Hardly had... when...', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_160', 'lop_12', 'van_dung_cao', 'published', 'grammar', 'Rewrite the sentence: ''She hasn''t eaten sushi since she was in Tokyo three years ago.''', '["A. The last time she ate sushi was when she was in Tokyo three years ago.","B. She last eaten sushi three years ago in Tokyo.","C. It is three years since she hasn''t eaten sushi.","D. This is the first time she ate sushi in Tokyo."]', 'A', 'Biến đổi thì hiện tại hoàn thành phủ định: S + haven''t/hasn''t + P.P + since... -> The last time + S + V-ed + was...', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_161', 'lop_11', 'nhan_biet', 'published', 'grammar', 'Rewrite the sentence: ''It is said that the company lost millions of dollars during the crisis.''', '["A. The company is said to have lost millions of dollars during the crisis.","B. The company was said to lose millions of dollars during the crisis.","C. The company is said to lose millions of dollars during the crisis.","D. Millions of dollars are said to lost by the company."]', 'A', 'Bị động khách quan khác thì: Mệnh đề chính ở hiện tại (is said), mệnh đề phụ ở quá khứ (lost) -> dùng ''to have + P.P'' (to have lost).', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_162', 'lop_11', 'thong_hieu', 'published', 'grammar', 'Rewrite: ''I''d rather you didn''t smoke in here.'' -> ''I would prefer ______.''', '["A. you not to smoke in here.","B. you didn''t smoke in here.","C. you not smoking in here.","D. you haven''t smoked in here."]', 'A', 'Prefer sb (not) to V = Would rather sb + V-ed. ''I would prefer you not to smoke in here''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_163', 'lop_8', 'van_dung', 'published', 'grammar', 'Rewrite: ''Shall we go to the museum this weekend?'' -> ''How about ______?''', '["A. going to the museum this weekend?","B. to go to the museum this weekend?","C. we go to the museum this weekend?","D. go to the museum this weekend?"]', 'A', 'Cấu trúc đề xuất gợi ý: Shall we + V-inf? = How about / What about + V-ing? = Let''s + V-inf.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_164', 'lop_11', 'van_dung_cao', 'published', 'grammar', 'He was out of breath because he ______ for half an hour. (Biến thể 1)', '["A. had been running","B. was running","C. has run","D. ran"]', 'A', 'Nhấn mạnh quá trình chạy diễn ra liên tục gây nên hậu quả thở dốc.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_165', 'lop_11', 'nhan_biet', 'published', 'grammar', 'He was out of breath because he ______ for half an hour. (Biến thể 2)', '["A. had been running","B. was running","C. has run","D. ran"]', 'A', 'Nhấn mạnh quá trình chạy diễn ra liên tục gây nên hậu quả thở dốc.', NULL);
