INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_387', 'lop_8', 'van_dung', 'published', 'vocabulary', 'Nomadic children learn to ________ horses at a very young age.', '["A. ride","B. drive","C. sail","D. fly"]', 'A', 'Cưỡi ngựa là ''ride horses''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_388', 'lop_8', 'van_dung_cao', 'published', 'grammar', 'He runs ________ than any other athlete in his class.', '["A. faster","B. more fast","C. fastly","D. fastest"]', 'A', 'Trạng từ fast có dạng so sánh hơn là ''faster''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_389', 'lop_8', 'nhan_biet', 'published', 'grammar', 'Vietnam is a multi-ethnic country with ________ distinct ethnic groups.', '["A. 54","B. 50","C. 64","D. 44"]', 'A', 'Việt Nam có 54 dân tộc anh em.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_390', 'lop_8', 'thong_hieu', 'published', 'vocabulary', 'Ethnic women weave intricate ________ fabrics using natural cotton.', '["A. brocade","B. plastic","C. paper","D. metal"]', 'A', 'Vải thổ cẩm là ''brocade fabrics''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_391', 'lop_8', 'van_dung', 'published', 'grammar', 'The communal house called ''Rong'' is the cultural heart of ethnic villages in the ________ Highlands.', '["A. Central","B. Northern","C. Southern","D. Western"]', 'A', 'Tây Nguyên là ''Central Highlands''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_392', 'lop_8', 'van_dung_cao', 'published', 'grammar', 'You ________ take off your shoes before entering a pagoda in Vietnam.', '["A. should","B. shouldn''t","C. must not","D. needn''t"]', 'A', 'Lời khuyên chuẩn mực văn hóa: ''should take off your shoes''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_393', 'lop_8', 'nhan_biet', 'published', 'grammar', 'There is a custom of ________ peach blossoms during Tet in the North.', '["A. displaying","B. display","C. displayed","D. displays"]', 'A', 'Sau giới từ of dùng V-ing: ''displaying''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_394', 'lop_8', 'thong_hieu', 'published', 'grammar', 'Unlike urban teenagers, ethnic children spend plenty of time ________ outside in nature.', '["A. playing","B. play","C. played","D. to play"]', 'A', 'Spend time + V-ing: ''spending time playing''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_395', 'lop_8', 'van_dung', 'published', 'vocabulary', 'Muong women wear beautiful headscarves and long wrap-around ________.', '["A. skirts","B. jeans","C. shorts","D. trousers"]', 'A', 'Váy dài quấn truyền thống của phụ nữ Mường: ''skirts''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_396', 'lop_8', 'van_dung_cao', 'published', 'vocabulary', 'Terraced fields in Sapa look like giant staircases climbing up to the ________.', '["A. clouds","B. river","C. sea","D. ground"]', 'A', 'Ruộng bậc thang như bậc thang chạm tới mây trời: ''clouds''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_397', 'lop_8', 'nhan_biet', 'published', 'vocabulary', 'It is considered ________ to point fingers directly at elderly people.', '["A. impolite","B. polite","C. respectful","D. kind"]', 'A', 'Chỉ tay vào người lớn tuổi là bất lịch sự -> ''impolite''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_398', 'lop_8', 'thong_hieu', 'published', 'grammar', 'They held an open-air campfire where everyone danced the joyful ''Xoe'' ________.', '["A. dance","B. song","C. game","D. dish"]', 'A', 'Điệu múa Xòe Thái: ''Xoe dance''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_399', 'lop_9', 'van_dung', 'published', 'grammar', 'We are really looking forward ________ visiting Bat Trang ceramic village.', '["A. to","B. at","C. for","D. with"]', 'A', 'Cụm ''look forward to + V-ing'' (rất trông đợi).', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_400', 'lop_9', 'van_dung_cao', 'published', 'vocabulary', 'This delicate silk-weaving technique was passed ________ through four generations.', '["A. down","B. off","C. up","D. away"]', 'A', 'Truyền lại qua nhiều thế hệ: ''pass down''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_401', 'lop_9', 'nhan_biet', 'published', 'vocabulary', 'He had to turn ________ the job offer because the commute was too exhausting.', '["A. down","B. on","C. up","D. off"]', 'A', 'Từ chối lời mời là ''turn down''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_402', 'lop_9', 'thong_hieu', 'published', 'grammar', 'City planners must find effective ways to deal ________ urban traffic congestion.', '["A. with","B. on","C. at","D. in"]', 'A', 'Giải quyết xử lý vấn đề: ''deal with''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_403', 'lop_9', 'van_dung', 'published', 'grammar', 'Secondary students study relentlessly to keep up ________ the demanding curriculum.', '["A. with","B. to","C. on","D. at"]', 'A', 'Theo kịp chương trình: ''keep up with''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_404', 'lop_9', 'van_dung_cao', 'published', 'grammar', 'The craftsman ________ sculpted this marble statue won first prize at the festival.', '["A. who","B. which","C. whom","D. whose"]', 'A', 'Đại từ quan hệ chỉ người làm chủ ngữ: ''who''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_405', 'lop_9', 'nhan_biet', 'published', 'grammar', 'If I ________ enough money, I would purchase a solar-powered water heater.', '["A. had","B. have","C. will have","D. have had"]', 'A', 'Câu điều kiện loại 2 giả định hiện tại: If + S + V-ed (''had'').', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_406', 'lop_9', 'thong_hieu', 'published', 'grammar', 'She asked me ________ I had visited Van Phuc silk village before.', '["A. whether","B. weather","C. what","D. that"]', 'A', 'Câu gián tiếp dạng Yes/No question dùng ''whether'' hoặc ''if''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_407', 'lop_9', 'van_dung', 'published', 'grammar', 'The ancient town attracts millions of tourists ________ it preserves authentic French villas.', '["A. because","B. although","C. despite","D. but"]', 'A', 'Mệnh đề nguyên nhân: ''because'' + mệnh đề.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_408', 'lop_9', 'van_dung_cao', 'published', 'grammar', 'Despite ________ exhausted after the long hike, they smiled happily at the mountain summit.', '["A. feeling","B. feel","C. felt","D. to feel"]', 'A', 'Sau giới từ Despite dùng V-ing: ''feeling''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_409', 'lop_9', 'nhan_biet', 'published', 'grammar', 'You haven''t submitted your mock exam paper yet, ________?', '["A. have you","B. haven''t you","C. do you","D. did you"]', 'A', 'Câu hỏi đuôi với vế trước phủ định ''haven''t'' -> ''have you?''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_410', 'lop_9', 'thong_hieu', 'published', 'vocabulary', 'The subway system helps shorten the daily ________ time for downtown commuters.', '["A. travel","B. walk","C. stay","D. live"]', 'A', 'Thời gian di chuyển đi lại: ''travel time'' hoặc ''commute''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_411', 'lop_9', 'van_dung', 'published', 'grammar', 'I wish our classroom ________ equipped with interactive smartboards.', '["A. were","B. is","C. will be","D. has been"]', 'A', 'Câu ước ở hiện tại dùng ''were'' cho mọi ngôi.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_412', 'lop_9', 'van_dung_cao', 'published', 'vocabulary', 'The local pottery workshop is facing severe financial ________ due to raw material costs.', '["A. difficulties","B. happiness","C. comforts","D. pleasures"]', 'A', 'Khó khăn tài chính: ''financial difficulties''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_413', 'lop_9', 'nhan_biet', 'published', 'grammar', 'Unless you practice speaking English regularly, you ________ improve your fluency.', '["A. will not","B. will","C. would","D. do"]', 'A', 'Unless = If not: ''Unless you practice..., you will not improve...''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_414', 'lop_9', 'thong_hieu', 'published', 'phonics', 'Choose the word with different sound in the underlined part: kn<u>i</u>fe, sk<u>i</u>ll, fl<u>i</u>ght, k<u>i</u>te', '["A. skill","B. knife","C. flight","D. kite"]', 'A', '''skill'' phát âm là /ɪ/, trong khi ba từ còn lại phát âm là /aɪ/.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_415', 'lop_9', 'van_dung', 'published', 'phonics', 'Choose the word with different stress pattern: po''llution, pre''serve, ''heritage, con''tinue', '["A. heritage","B. pollution","C. preserve","D. continue"]', 'A', '''heritage'' trọng âm 1, các từ còn lại trọng âm 2.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_416', 'lop_9', 'van_dung_cao', 'published', 'vocabulary', 'The ancient citadel was recognised by UNESCO as a World Cultural ________.', '["A. Heritage","B. Tradition","C. Custom","D. Miracle"]', 'A', 'Di sản văn hóa thế giới: ''World Cultural Heritage''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_417', 'lop_9', 'nhan_biet', 'published', 'vocabulary', 'If farmers continue to overuse chemical pesticides, the groundwater will become ________.', '["A. contaminated","B. pure","C. clean","D. fresh"]', 'A', 'Bị ô nhiễm nhiễm độc: ''contaminated''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_418', 'lop_9', 'thong_hieu', 'published', 'grammar', 'The English teacher suggested that we ________ reading English news headlines daily.', '["A. should practice","B. to practice","C. practiced","D. practicing"]', 'A', 'Cấu trúc giả định: suggest that S + (should) + V nguyên mẫu.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_419', 'lop_9', 'van_dung', 'published', 'grammar', 'I cannot find my car keys anywhere. I ________ them on my office desk.', '["A. must have left","B. should leave","C. can leave","D. must leave"]', 'A', 'Suy đoán chắc chắn việc đã xảy ra trong quá khứ: ''must have left''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_420', 'lop_9', 'van_dung_cao', 'published', 'grammar', 'The book ________ I bought at the book fair yesterday is exceptionally inspiring.', '["A. which","B. who","C. whom","D. where"]', 'A', 'Đại từ quan hệ thay thế cho cuốn sách (vật): ''which''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_421', 'lop_9', 'nhan_biet', 'published', 'grammar', 'Find the underlined error: <u>Although</u> his broken leg, he <u>managed</u> to <u>climb</u> up to <u>the top</u>.', '["A. Although","B. managed","C. climb","D. the top"]', 'A', 'Sau cụm danh từ ''his broken leg'' phải dùng ''In spite of'' hoặc ''Despite'', không dùng ''Although''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_422', 'lop_9', 'thong_hieu', 'published', 'vocabulary', 'He is said to be the most ________ craftsman in the bronze casting village.', '["A. skilled","B. skillful","C. skill","D. unskilled"]', 'A', 'Nghệ nhân lành nghề khéo léo: ''skilled'' craftsman.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_423', 'lop_9', 'van_dung', 'published', 'grammar', 'Rewrite test: ''They began restoring the pagoda three years ago.'' -> ''They have...''', '["A. been restoring the pagoda for three years.","B. restored the pagoda since three years.","C. restored the pagoda three years ago.","D. restore the pagoda for three years."]', 'A', 'Chuyển từ quá khứ đơn sang hiện tại hoàn thành với ''for three years''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_424', 'lop_9', 'van_dung_cao', 'published', 'grammar', 'Would you mind ________ down the air conditioner? It''s freezing here.', '["A. turning","B. turn","C. to turn","D. turned"]', 'A', 'Sau ''Would you mind'' dùng V-ing: ''turning down''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_425', 'lop_9', 'nhan_biet', 'published', 'grammar', 'Hoi An is famous ________ its picturesque lantern-lit streets and yellow houses.', '["A. for","B. with","C. to","D. at"]', 'A', 'Nổi tiếng vì điều gì: ''famous for''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_426', 'lop_9', 'thong_hieu', 'published', 'grammar', 'If you work harder, you will get better results. -> The harder you work, ________.', '["A. the better results you get","B. better results you get","C. the best results you get","D. you get better results"]', 'A', 'Cấu trúc so sánh kép: The + comp, the + comp.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_427', 'lop_9', 'van_dung', 'published', 'vocabulary', 'Solar power is an eco-friendly source of energy because it does not emit greenhouse ________.', '["A. gases","B. smokes","C. dusts","D. steams"]', 'A', 'Khí nhà kính: ''greenhouse gases''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_428', 'lop_9', 'van_dung_cao', 'published', 'grammar', 'She couldn''t attend the study session ________ she had caught a severe cold.', '["A. since","B. although","C. despite","D. so"]', 'A', 'Liên từ chỉ nguyên nhân: ''since'' (= because).', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_429', 'lop_9', 'nhan_biet', 'published', 'vocabulary', 'My grandparents prefer living in the countryside because the pace of life is ________.', '["A. slower","B. slowest","C. slowly","D. more slow"]', 'A', 'Nhịp sống chậm rãi hơn: ''slower''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_430', 'lop_9', 'thong_hieu', 'published', 'grammar', 'I don''t know how to operate this 3D printer. -> I wish I ________ how to operate it.', '["A. knew","B. know","C. have known","D. will know"]', 'A', 'Câu ước hiện tại: wish + S + V quá khứ đơn (''knew'').', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_431', 'lop_9', 'van_dung', 'published', 'grammar', 'The environmental project was initiated ________ raise local awareness about recycling.', '["A. in order to","B. so that","C. because","D. although"]', 'A', 'Mục đích làm gì: ''in order to + V nguyên mẫu''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_432', 'lop_9', 'van_dung_cao', 'published', 'grammar', 'By the time we reached the cinema, the movie ________ already started.', '["A. had","B. has","C. was","D. is"]', 'A', 'Phối hợp thì By the time + quá khứ đơn, quá khứ hoàn thành (''had started'').', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_433', 'lop_9', 'nhan_biet', 'published', 'grammar', 'Could you show me the way to the national stadium? -> ________', '["A. Go straight ahead, then turn right at the crossroads.","B. Yes, I do.","C. No, I am not.","D. It''s expensive."]', 'A', 'Chỉ dẫn đường đi lịch sự.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_434', 'lop_10', 'thong_hieu', 'published', 'vocabulary', 'In many modern families, both parents share the financial burden as co-________.', '["A. breadwinners","B. homemakers","C. children","D. servants"]', 'A', 'Người trụ cột kiếm tiền nuôi gia đình: ''breadwinner''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_435', 'lop_10', 'van_dung', 'published', 'grammar', 'Household chores ________ equally among all members of our family.', '["A. are divided","B. divide","C. is divided","D. dividing"]', 'A', 'Bị động số nhiều hiện tại đơn: ''chores are divided''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_436', 'lop_10', 'van_dung_cao', 'published', 'vocabulary', 'Sharing chores teaches teenagers how to become self-________ and responsible.', '["A. reliant","B. heavy","C. full","D. sick"]', 'A', 'Tự lực cánh sinh: ''self-reliant''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_437', 'lop_10', 'nhan_biet', 'published', 'grammar', 'Rubbish ________ out every evening after the kitchen is tidied up.', '["A. is taken","B. takes","C. took","D. is taking"]', 'A', 'Rác được đem đổ: ''Rubbish is taken out''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_438', 'lop_10', 'thong_hieu', 'published', 'vocabulary', 'Doing chores together strengthens the emotional ________ between family members.', '["A. bond","B. chain","C. wall","D. lock"]', 'A', 'Mối liên kết tình cảm gắn bó: ''emotional bond''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_439', 'lop_10', 'van_dung', 'published', 'vocabulary', 'Switching off lights when leaving the room helps reduce our household carbon ________.', '["A. footprint","B. print","C. shadow","D. path"]', 'A', 'Dấu chân carbon phát thải: ''carbon footprint''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_440', 'lop_10', 'van_dung_cao', 'published', 'vocabulary', 'Single-use plastic bottles take hundreds of years to ________ in landfills.', '["A. decompose","B. grow","C. produce","D. build"]', 'A', 'Phân hủy tự nhiên: ''decompose''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_441', 'lop_10', 'nhan_biet', 'published', 'grammar', 'If everyone ________ public transport, air pollution in downtown areas would drop sharply.', '["A. used","B. uses","C. will use","D. has used"]', 'A', 'Câu điều kiện loại 2 giả định hiện tại: ''If everyone used... would drop''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_442', 'lop_10', 'thong_hieu', 'published', 'vocabulary', 'Eco-friendly products made from bamboo are completely ________ and non-toxic.', '["A. biodegradable","B. synthetic","C. chemical","D. poisonous"]', 'A', 'Có thể phân hủy sinh học: ''biodegradable''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_443', 'lop_10', 'van_dung', 'published', 'vocabulary', 'The school environmental club was established to raise student ________ about climate change.', '["A. awareness","B. aware","C. unaware","D. awarenesses"]', 'A', 'Nâng cao nhận thức: ''raise student awareness''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_444', 'lop_10', 'van_dung_cao', 'published', 'grammar', 'Many coastal species are facing extinction because their natural habitats are being ________.', '["A. destroyed","B. preserve","C. creating","D. protecting"]', 'A', 'Bị động tiếp diễn: ''are being destroyed''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_445', 'lop_10', 'nhan_biet', 'published', 'grammar', 'Unless we take immediate actions, our oceans ________ filled with more plastic than fish by 2050.', '["A. will be","B. are","C. would be","D. had been"]', 'A', 'Câu điều kiện loại 1: Unless + hiện tại đơn, tương lai đơn (''will be'').', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_446', 'lop_10', 'thong_hieu', 'published', 'vocabulary', 'Wind turbines and solar panels generate ________ energy without emitting greenhouse gases.', '["A. clean","B. dirty","C. toxic","D. fossil"]', 'A', 'Năng lượng sạch: ''clean energy''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_447', 'lop_10', 'van_dung', 'published', 'grammar', 'She volunteered to clean ________ the local canal on World Environment Day.', '["A. up","B. off","C. out","D. down"]', 'A', 'Dọn sạch rác thải: ''clean up''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_448', 'lop_10', 'van_dung_cao', 'published', 'grammar', 'Can you tell me how to sort recyclables? -> ________', '["A. Put paper and plastics into the green bin and organic waste into the brown one.","B. Yes, I do.","C. No, I am busy.","D. It is raining."]', 'A', 'Hướng dẫn phân loại rác thải tái chế.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_449', 'lop_11', 'nhan_biet', 'published', 'vocabulary', 'Conflicts often arise between parents and teenagers due to the generation ________.', '["A. gap","B. bridge","C. wall","D. hole"]', 'A', 'Khoảng cách thế hệ: ''generation gap''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_450', 'lop_11', 'thong_hieu', 'published', 'grammar', 'You ________ respect your grandparents'' traditional viewpoints even if you disagree.', '["A. should","B. shouldn''t","C. mustn''t","D. needn''t"]', 'A', 'Lời khuyên đạo đức: ''should respect''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_451', 'lop_11', 'van_dung', 'published', 'vocabulary', 'Open and honest communication helps bridge the ideological ________ between generations.', '["A. divide","B. border","C. cut","D. fence"]', 'A', 'Sự ngăn cách, bất đồng quan điểm: ''ideological divide''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_452', 'lop_11', 'van_dung_cao', 'published', 'grammar', 'According to school regulations, all students ________ wear their identity cards on campus.', '["A. must","B. should","C. may","D. can"]', 'A', 'Quy định bắt buộc của tổ chức: ''must wear''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_453', 'lop_11', 'nhan_biet', 'published', 'grammar', 'Many parents impose strict curfews because they worry ________ their children''s safety at night.', '["A. about","B. with","C. on","D. to"]', 'A', 'Lo lắng về điều gì: ''worry about''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_454', 'lop_11', 'thong_hieu', 'published', 'grammar', 'Vietnam officially joined the Association of Southeast Asian Nations (ASEAN) in ________.', '["A. 1995","B. 1990","C. 2000","D. 1986"]', 'A', 'Việt Nam gia nhập ASEAN vào năm 1995.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_455', 'lop_11', 'van_dung', 'published', 'grammar', '________ the museum exhibition thoroughly, the students submitted an insightful research paper.', '["A. Having visited","B. Have visited","C. Visited","D. Visit"]', 'A', 'Mệnh đề phân từ hoàn thành chỉ hành động xảy ra trước: ''Having visited''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_456', 'lop_11', 'van_dung_cao', 'published', 'grammar', 'Trang An Scenic Landscape Complex is Vietnam''s only UNESCO World ________ Heritage site.', '["A. Mixed","B. Cultural","C. Natural","D. Artificial"]', 'A', 'Tràng An là di sản hỗn hợp (cả văn hóa và thiên nhiên): ''Mixed Heritage''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_457', 'lop_11', 'nhan_biet', 'published', 'vocabulary', 'The summit aimed to foster economic cooperation and diplomatic ________ among member states.', '["A. solidarity","B. dispute","C. conflict","D. rival"]', 'A', 'Tình đoàn kết hữu nghị ngoại giao: ''diplomatic solidarity''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_458', 'lop_11', 'thong_hieu', 'published', 'grammar', 'She was commended for ________ helped organize the regional youth cultural exchange.', '["A. having","B. has","C. have","D. had"]', 'A', 'Sau giới từ for dùng danh động từ hoàn thành: ''for having helped''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_459', 'lop_11', 'van_dung', 'published', 'vocabulary', 'Preserving authentic intangible cultural heritage requires sustained financial and educational ________.', '["A. investment","B. destruction","C. ignorance","D. neglect"]', 'A', 'Đầu tư tài chính và giáo dục: ''investment''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_460', 'lop_11', 'van_dung_cao', 'published', 'grammar', 'Quan Ho folk singing was inscribed on the Representative List of the Intangible Cultural Heritage of ________.', '["A. Humanity","B. Universe","C. Planet","D. Nature"]', 'A', 'Di sản văn hóa phi vật thể của nhân loại: ''Heritage of Humanity''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_461', 'lop_11', 'nhan_biet', 'published', 'grammar', '________ from a distance, the imperial citadel looks majestic against the blue sky.', '["A. Viewed","B. Viewing","C. View","D. To view"]', 'A', 'Phân từ quá khứ mang nghĩa bị động (được nhìn từ xa): ''Viewed from a distance''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_462', 'lop_11', 'thong_hieu', 'published', 'vocabulary', 'Youth ambassadors act as bridges to promote mutual ________ across diverse cultural backgrounds.', '["A. understanding","B. misunderstanding","C. doubt","D. skepticism"]', 'A', 'Sự hiểu biết lẫn nhau: ''mutual understanding''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_463', 'lop_11', 'van_dung', 'published', 'grammar', 'Congratulations on winning the ASEAN scholarship! -> ________', '["A. Thank you so much, it means the world to me!","B. No problem.","C. You''re welcome.","D. Never mind."]', 'A', 'Đáp lại lời chúc mừng nồng nhiệt.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_464', 'lop_12', 'van_dung_cao', 'published', 'grammar', 'Seldom ________ such an eloquent and persuasive keynote address on artificial intelligence.', '["A. have I heard","B. I have heard","C. did I heard","D. I had heard"]', 'A', 'Đảo ngữ với phó từ phủ định ''Seldom'' đứng đầu câu: trợ động từ + S + V.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_465', 'lop_12', 'nhan_biet', 'published', 'grammar', 'It was her remarkable perseverance ________ enabled her to overcome insurmountable obstacles.', '["A. that","B. which","C. whom","D. where"]', 'A', 'Cấu trúc câu chẻ nhấn mạnh: ''It is/was... that...''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_466', 'lop_12', 'thong_hieu', 'published', 'grammar', 'Not only ________ late for the interview, but he also forgot to bring his credentials.', '["A. was he","B. he was","C. is he","D. he is"]', 'A', 'Đảo ngữ ''Not only was he late...''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_467', 'lop_12', 'van_dung', 'published', 'grammar', 'Hardly ________ into the library when the fire alarm began to ring loudly.', '["A. had she stepped","B. she had stepped","C. did she stepped","D. has she stepped"]', 'A', 'Cấu trúc ''Hardly had + S + V3... when...''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_468', 'lop_12', 'van_dung_cao', 'published', 'grammar', 'Under no circumstances ________ you share your banking passwords with third parties.', '["A. should","B. you should","C. must you not","D. you must"]', 'A', 'Đảo ngữ với ''Under no circumstances should you...''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_469', 'lop_12', 'nhan_biet', 'published', 'vocabulary', 'The rapid pace of ________ has drawn rural workers toward major metropolitan centers. (URBAN)', '["A. urbanization","B. urbanist","C. urbanite","D. urbanity"]', 'A', 'Danh từ chỉ quá trình đô thị hóa: ''urbanization''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_470', 'lop_12', 'thong_hieu', 'published', 'vocabulary', 'Solar power is an infinitely ________ source of energy compared to coal and oil. (RENEW)', '["A. renewable","B. renewed","C. renewing","D. renewal"]', 'A', 'Tính từ năng lượng tái tạo: ''renewable''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_471', 'lop_12', 'van_dung', 'published', 'vocabulary', 'His argument was utterly ________ and lacked empirical evidence. (CONVINCE)', '["A. unconvincing","B. convincing","C. convinced","D. unconvinced"]', 'A', 'Tiền tố phủ định un- chỉ tính chất không thuyết phục: ''unconvincing''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_472', 'lop_12', 'van_dung_cao', 'published', 'vocabulary', 'The municipal council demonstrated commendable ________ in managing the public health crisis. (DECIDE)', '["A. decisiveness","B. decision","C. decisive","D. indecision"]', 'A', 'Phẩm chất quyết đoán kiên quyết: ''decisiveness''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_473', 'lop_12', 'nhan_biet', 'published', 'vocabulary', 'High school students should develop ________ thinking skills to evaluate online claims. (CRITIC)', '["A. critical","B. criticize","C. criticism","D. critically"]', 'A', 'Tư duy phản biện: ''critical thinking''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_474', 'lop_12', 'thong_hieu', 'published', 'grammar', 'The ancient castle has been ________ restored to its original fourteenth-century grandeur. (METICULOUS)', '["A. meticulously","B. meticulous","C. meticulousness","D. meticulouslyly"]', 'A', 'Phó từ bổ nghĩa cho động từ restored: ''meticulously'' (tỉ mỉ, cẩn trọng).', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_475', 'lop_12', 'van_dung', 'published', 'vocabulary', 'Excessive smartphone usage can be severely ________ to adolescents'' mental well-being. (DETRIMENT)', '["A. detrimental","B. detriment","C. detrimentally","D. undetrimental"]', 'A', 'Có hại, gây tổn hại: tính từ ''detrimental to''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_476', 'lop_12', 'van_dung_cao', 'published', 'vocabulary', 'Artificial intelligence is revolutionizing data ________ across banking and finance. (PROCESS)', '["A. processing","B. processor","C. processed","D. processual"]', 'A', 'Xử lý dữ liệu: ''data processing''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_477', 'lop_12', 'nhan_biet', 'published', 'vocabulary', 'A benevolent ________ donated five million dollars to build a cancer hospital. (BENEFACTOR)', '["A. benefactor","B. benefaction","C. beneficial","D. beneficiary"]', 'A', 'Nhà hảo tâm làm từ thiện: ''benefactor''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_478', 'lop_12', 'thong_hieu', 'published', 'vocabulary', 'She achieved ________ fluency in Japanese after studying in Tokyo for four years. (IMPRESS)', '["A. impressive","B. impressed","C. impression","D. impressively"]', 'A', 'Độ lưu loát ấn tượng: tính từ ''impressive''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_479', 'lop_12', 'van_dung', 'published', 'phonics', 'Choose the word whose underlined part is pronounced differently: breath<u>es</u>, bat<u>es</u>, cloth<u>es</u>, toothach<u>es</u>', '["A. bathes","B. breathes","C. clothes","D. toothaches"]', 'D', '''toothaches'' kết thúc bằng âm /ks/, đuôi phát âm là /s/, ba từ còn lại có đuôi phát âm là /z/.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_480', 'lop_12', 'van_dung_cao', 'published', 'phonics', 'Choose the word with different primary stress: e''conomy, com''mitment, ,under''stand, de''livery', '["A. understand","B. economy","C. commitment","D. delivery"]', 'A', '''understand'' trọng âm 3, các từ còn lại trọng âm 2.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_481', 'lop_12', 'nhan_biet', 'published', 'grammar', 'Had he known about the severe traffic bottleneck, he ________ an alternate route. (Mixed Conditional)', '["A. would have taken","B. would take","C. took","D. will take"]', 'A', 'Đảo ngữ câu điều kiện loại 3: Had + S + V3, S + would have + V3.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_482', 'lop_12', 'thong_hieu', 'published', 'vocabulary', 'The new CEO introduced pragmatic measures to ________ the company''s financial viability. (Collocation)', '["A. bolster","B. push","C. lift","D. pull"]', 'A', 'Tăng cường, củng cố tính khả thi tài chính: ''bolster financial viability''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_483', 'lop_12', 'van_dung', 'published', 'vocabulary', 'Choose the word CLOSEST in meaning to ''tenacious'': The detective was tenacious in pursuing the truth.', '["A. persistent","B. indifferent","C. hesitant","D. careless"]', 'A', '''tenacious'' đồng nghĩa với ''persistent'' (kiên trì, bền bỉ bám đuổi).', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_484', 'lop_12', 'van_dung_cao', 'published', 'vocabulary', 'Choose the word OPPOSITE in meaning to ''altruistic'': His actions were deemed entirely altruistic.', '["A. selfish","B. generous","C. benevolent","D. charitable"]', 'A', '''altruistic'' (vị tha, hy sinh) trái nghĩa với ''selfish'' (ích kỷ).', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_485', 'lop_12', 'nhan_biet', 'published', 'grammar', 'No sooner ________ the contract than a lucrative counteroffer was presented by a rival firm.', '["A. had they signed","B. they had signed","C. did they sign","D. were they signing"]', 'A', 'Cấu trúc đảo ngữ ''No sooner had + S + V3 than...''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_486', 'lop_12', 'thong_hieu', 'published', 'grammar', 'Find the error: The committee <u>insisted</u> that the budget <u>is</u> revised <u>prior to</u> the <u>annual</u> general meeting.', '["A. is","B. insisted","C. prior to","D. annual"]', 'A', 'Cấu trúc bàng thái cách Subjunctive: insist that S + (should) + be revised, không dùng ''is''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_487', 'lop_12', 'van_dung', 'published', 'vocabulary', 'The documentary offered a profound glimpse into the fragile marine ________ of the Great Barrier Reef.', '["A. ecosystem","B. economics","C. geology","D. meteorology"]', 'A', 'Hệ sinh thái biển mong manh: ''fragile marine ecosystem''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_488', 'lop_12', 'van_dung_cao', 'published', 'grammar', 'She is fluent in French, German, and Spanish; ________, she has conversational mastery of Mandarin.', '["A. furthermore","B. nevertheless","C. whereas","D. otherwise"]', 'A', 'Liên từ bổ sung thông tin tích cực: ''furthermore'' (hơn nữa, thêm vào đó).', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_489', 'lop_12', 'nhan_biet', 'published', 'grammar', 'It is imperative that every citizen ________ full responsibility for environmental protection.', '["A. take","B. takes","C. took","D. is taking"]', 'A', 'Thức giả định: It is imperative that + S + V nguyên mẫu (''take'').', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_490', 'lop_12', 'thong_hieu', 'published', 'vocabulary', 'The candidate delivered an exceptionally ________ speech that swayed undecided voters.', '["A. eloquent","B. silent","C. mute","D. awkward"]', 'A', 'Bài phát biểu hùng biện lưu loát: ''eloquent speech''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_491', 'lop_12', 'van_dung', 'published', 'grammar', 'The historical novel was so captivating that I couldn''t put it down. -> So captivating ________.', '["A. was the historical novel that I couldn''t put it down","B. the historical novel was that I couldn''t put it down","C. was that the novel I couldn''t put down","D. that the historical novel was I couldn''t put it down"]', 'A', 'Đảo ngữ với So + adj + be + S + that...', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_492', 'lop_12', 'van_dung_cao', 'published', 'vocabulary', 'In urban planning, balancing modernization with historical ________ is a paramount challenge.', '["A. preservation","B. devastation","C. demolition","D. destruction"]', 'A', 'Bảo tồn di sản lịch sử: ''historical preservation''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_493', 'lop_12', 'nhan_biet', 'published', 'vocabulary', 'The young apprentice proved himself to be extraordinarily ________ in mastering complex algorithms.', '["A. diligent","B. indolent","C. lazy","D. sluggish"]', 'A', 'Chăm chỉ, cần mẫn: ''diligent''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_494', 'lop_12', 'thong_hieu', 'published', 'grammar', 'Neither the director nor his assistants ________ aware of the data breach until this morning.', '["A. were","B. was","C. is","D. has been"]', 'A', 'Neither A nor B: động từ hòa hợp theo chủ ngữ gần nhất ''assistants'' (số nhiều quá khứ -> ''were'').', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_495', 'lop_12', 'van_dung', 'published', 'vocabulary', 'The newly constructed suspension bridge has significantly eased suburban ________.', '["A. congestion","B. space","C. calmness","D. silence"]', 'A', 'Ùn tắc giao thông: ''traffic congestion''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_496', 'lop_12', 'van_dung_cao', 'published', 'grammar', 'He wouldn''t have failed the licensing exam if he ________ more attention during lectures.', '["A. had paid","B. paid","C. would pay","D. pays"]', 'A', 'Điều kiện loại 3: If + S + had + V3 (''had paid'').', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_497', 'lop_12', 'nhan_biet', 'published', 'vocabulary', 'Scientists are investigating whether biodegradable plastics can safely break down in cold marine ________.', '["A. environments","B. factories","C. machines","D. rooms"]', 'A', 'Môi trường biển lạnh giá: ''marine environments''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_498', 'lop_12', 'thong_hieu', 'published', 'grammar', 'The debate team practiced late into the night; ________, they won the national championship cup.', '["A. consequently","B. however","C. whereas","D. despite"]', 'A', 'Chỉ kết quả: ''consequently'' (kết quả là, do đó).', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_499', 'lop_12', 'van_dung', 'published', 'grammar', 'Rarely ________ seen such an overwhelming display of public solidarity after a natural catastrophe.', '["A. has the nation","B. the nation has","C. did the nation","D. is the nation"]', 'A', 'Đảo ngữ với Rarely: ''Rarely has the nation seen...''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_500', 'lop_12', 'van_dung_cao', 'published', 'vocabulary', 'The company adopted a ________ approach to restructuring that minimized workforce layoffs.', '["A. pragmatic","B. careless","C. reckless","D. hasty"]', 'A', 'Phương pháp thực tiễn, có căn cứ: ''pragmatic approach''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_501', 'lop_12', 'nhan_biet', 'published', 'grammar', 'Much as she respected her mentor, she ________ to accept his controversial proposition.', '["A. declined","B. agreed","C. welcomed","D. praised"]', 'A', 'Dù rất tôn trọng người thầy, cô vẫn từ chối lời đề nghị: ''declined''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_502', 'lop_12', 'thong_hieu', 'published', 'vocabulary', 'The university offers comprehensive ________ guidance for students transitioning into the labor market.', '["A. vocational","B. vocal","C. voice","D. vacation"]', 'A', 'Định hướng nghề nghiệp: ''vocational guidance''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_503', 'lop_12', 'van_dung', 'published', 'grammar', 'I appreciate your unwavering guidance and support throughout my thesis research! -> ________', '["A. It was an absolute pleasure working alongside you.","B. No thanks.","C. Yes, please.","D. It doesn''t matter."]', 'A', 'Phản hồi học thuật lịch sự, chân thành.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_504', 'lop_7', 'van_dung_cao', 'published', 'reading', 'Notice: ''Please keep off the grass!'' -> What does this mean?', '["A. Do not walk on the grass","B. You can play football on the grass","C. Cut the grass now","D. Water the grass"]', 'A', 'Biển báo ''Keep off the grass'' nghĩa là không được giẫm lên cỏ.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_505', 'lop_7', 'nhan_biet', 'published', 'reading', 'Notice: ''Buy one coffee, get one free before 9:00 AM!'' -> What does this mean?', '["A. Morning coffee is cheaper","B. Coffee is served only at 9:00 AM","C. You cannot buy coffee in the morning","D. Coffee is free all day"]', 'A', 'Mua 1 tặng 1 trước 9h nghĩa là cà phê buổi sáng rẻ hơn.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_506', 'lop_7', 'thong_hieu', 'published', 'vocabulary', 'I need to buy a return train ________ to Oxford.', '["A. ticket","B. book","C. letter","D. stamp"]', 'A', 'Vé tàu khứ hồi: ''return train ticket''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_507', 'lop_7', 'van_dung', 'published', 'vocabulary', 'Can you help me ________ my lost luggage at the airport counter?', '["A. find","B. look","C. see","D. watch"]', 'A', 'Tìm hành lý thất lạc: ''find my lost luggage''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_508', 'lop_7', 'van_dung_cao', 'published', 'vocabulary', 'The museum admission fee is ________ for children under 6 years old.', '["A. free","B. expensive","C. costly","D. high"]', 'A', 'Miễn phí cho trẻ em: ''free''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_509', 'lop_7', 'nhan_biet', 'published', 'reading', 'Email notice: ''Library renovation: The second floor will remain closed until Friday.'' What does this mean?', '["A. Students cannot access second floor books before Friday.","B. The entire library is closed forever.","C. Renovation starts on Friday.","D. The first floor is closed."]', 'A', 'Tầng 2 đóng cửa sửa chữa tới thứ Sáu nghĩa là học sinh không thể vào tầng 2 trước thứ Sáu.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_510', 'lop_7', 'thong_hieu', 'published', 'grammar', 'He is really keen ________ learning digital photography and photo editing.', '["A. on","B. in","C. at","D. with"]', 'A', 'Cụm ''keen on + V-ing'' (say mê, thích thú).', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_511', 'lop_7', 'van_dung', 'published', 'vocabulary', 'Although it rained cats and dogs, the outdoor music concert was not ________ off.', '["A. called","B. put","C. taken","D. made"]', 'A', 'Hủy bỏ buổi hòa nhạc: ''called off''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_512', 'lop_7', 'van_dung_cao', 'published', 'grammar', 'The hotel staff apologized for the unexpected delay in ________ our room.', '["A. preparing","B. prepare","C. prepared","D. preparation"]', 'A', 'Sau giới từ in dùng V-ing: ''preparing''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_513', 'lop_7', 'nhan_biet', 'published', 'grammar', 'She managed to solve the challenging crossword puzzle entirely on her ________.', '["A. own","B. self","C. single","D. alone"]', 'A', 'Cụm tự mình làm không cần trợ giúp: ''on her own''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_514', 'lop_7', 'thong_hieu', 'published', 'vocabulary', 'Governments should allocate substantial funding to ________ medical research on infectious diseases.', '["A. expedite","B. slow","C. delay","D. hinder"]', 'A', 'Thúc đẩy nhanh tiến độ nghiên cứu: ''expedite medical research''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_515', 'lop_7', 'van_dung', 'published', 'vocabulary', 'Deforestation contributes significantly to biodiversity loss, thereby ________ vulnerable wildlife populations.', '["A. jeopardizing","B. safe","C. securing","D. nurturing"]', 'A', 'Đe dọa, đặt vào vòng hiểm nguy: ''jeopardizing vulnerable populations''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_516', 'lop_7', 'van_dung_cao', 'published', 'vocabulary', 'Urban planners must adopt sustainable practices to ________ with the demands of rapid population influx.', '["A. cope","B. meet","C. lead","D. stand"]', 'A', 'Đương đầu và thích nghi với thách thức: ''cope with demands''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_517', 'lop_7', 'nhan_biet', 'published', 'vocabulary', 'There is compelling empirical evidence demonstrating the ________ correlation between regular exercise and longevity.', '["A. positive","B. hostile","C. negative","D. false"]', 'A', 'Mối tương quan đồng thuận tích cực: ''positive correlation''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_518', 'lop_7', 'thong_hieu', 'published', 'vocabulary', 'Proponents argue that artificial intelligence will ________ unprecedented productivity across global economies.', '["A. catalyze","B. freeze","C. abolish","D. dampen"]', 'A', 'Xúc tác, thúc đẩy mạnh mẽ: ''catalyze productivity''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_519', 'lop_7', 'van_dung', 'published', 'reading', 'Notice: ''Swimming pool closed for water treatment from 1:00 PM to 3:00 PM.'' What is true?', '["A. You cannot swim between 1:00 PM and 3:00 PM.","B. The pool is open all day.","C. The pool is closed at night.","D. Swimming is free today."]', 'A', 'Hồ bơi đóng cửa xử lý nước từ 1h đến 3h chiều -> không được bơi trong khoảng thời gian này.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_520', 'lop_7', 'van_dung_cao', 'published', 'reading', 'Sign on bus door: ''Have exact change ready before boarding.'' What does the driver want?', '["A. Passengers to prepare the correct coins or notes in advance.","B. Passengers to pay after arriving.","C. Passengers to buy bus tickets online.","D. Passengers to travel for free."]', 'A', '''Exact change'' nghĩa là chuẩn bị sẵn tiền lẻ đúng số tiền vé trước khi lên xe.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_521', 'lop_7', 'nhan_biet', 'published', 'grammar', 'What time does the film start? -> ________ 7:30 PM.', '["A. At","B. In","C. On","D. For"]', 'A', 'Giờ giấc đi với giới từ ''At''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_522', 'lop_7', 'thong_hieu', 'published', 'vocabulary', 'I can''t go cycling today because my bicycle tire is ________.', '["A. flat","B. heavy","C. sharp","D. sweet"]', 'A', 'Lốp xe đạp bị xẹp/thủng: ''flat tire''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_523', 'lop_7', 'van_dung', 'published', 'grammar', 'Could you please tell me the way to the railway station? -> ________', '["A. Turn right at the traffic lights, it''s opposite the post office.","B. Yes, I do.","C. No, I am fine.","D. It is five dollars."]', 'A', 'Chỉ đường lịch sự trong giao tiếp tiếng Anh KET.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_524', 'lop_7', 'van_dung_cao', 'published', 'grammar', 'She is really looking forward to ________ her pen pal in London this summer.', '["A. meeting","B. meet","C. met","D. to meet"]', 'A', 'Cấu trúc look forward to + V-ing: ''meeting''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_525', 'lop_7', 'nhan_biet', 'published', 'grammar', 'We didn''t go on a picnic yesterday ________ the heavy downpour.', '["A. because of","B. because","C. although","D. despite of"]', 'A', 'Because of + cụm danh từ ''the heavy downpour''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_526', 'lop_7', 'thong_hieu', 'published', 'grammar', 'Excuse me, how much is this souvenir postcard? -> ________', '["A. It''s one pound fifty.","B. It''s blue.","C. It''s on the table.","D. It''s very tall."]', 'A', 'Hỏi giá tiền: ''It''s one pound fifty.''', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_527', 'lop_7', 'van_dung', 'published', 'grammar', 'My brother is fond of ________ old postage stamps and coins.', '["A. collecting","B. collect","C. collected","D. collects"]', 'A', 'Sau cụm tính từ fond of dùng V-ing: ''collecting''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_528', 'lop_7', 'van_dung_cao', 'published', 'vocabulary', 'What would you like for dessert? -> A slice of chocolate ________, please.', '["A. cake","B. meat","C. soup","D. rice"]', 'A', 'Món tráng miệng là bánh socola -> ''cake''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_529', 'lop_7', 'nhan_biet', 'published', 'reading', 'Notice in computer lab: ''Do not eat or drink near keyboards.'' Why?', '["A. To protect computer equipment from liquid damage.","B. Keyboards are made of food.","C. Food is sold in the lab.","D. Students must eat quickly."]', 'A', 'Bảo vệ bàn phím máy tính khỏi bị đổ nước làm hỏng.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_530', 'lop_7', 'thong_hieu', 'published', 'reading', 'Sign in museum: ''Photography permitted without flash.'' What can visitors do?', '["A. Take photos without using flash.","B. Take photos with bright flash only.","C. No cameras allowed at all.","D. Buy pictures from the gift shop."]', 'A', 'Được phép chụp ảnh nhưng không được dùng đèn flash.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_531', 'lop_7', 'van_dung', 'published', 'grammar', 'He ________ English since he was six years old.', '["A. has studied","B. studied","C. studies","D. is studying"]', 'A', 'Dấu hiệu ''since he was six'' dùng thì hiện tại hoàn thành: ''has studied''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_532', 'lop_7', 'van_dung_cao', 'published', 'grammar', 'The weather was warm and sunny, ________ we spent the entire afternoon at the beach.', '["A. so","B. but","C. because","D. although"]', 'A', 'Liên từ chỉ kết quả: ''so'' (vì vậy).', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_533', 'lop_7', 'nhan_biet', 'published', 'grammar', 'If it ________ tomorrow, we will stay indoors and play board games.', '["A. rains","B. will rain","C. rained","D. rain"]', 'A', 'Câu điều kiện loại 1: If + hiện tại đơn ngôi thứ 3 số ít: ''rains''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_534', 'lop_7', 'thong_hieu', 'published', 'grammar', 'Rewrite test: ''This suitcase is too heavy for me to lift.'' -> ''This suitcase isn''t...''', '["A. light enough for me to lift.","B. heavy enough for me to lift.","C. so light for me to lift.","D. too light for me to lift."]', 'A', 'Biến đổi cấu trúc: too adj to V -> not adj enough to V.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_535', 'lop_7', 'van_dung', 'published', 'grammar', 'The novel was written ________ a famous young author from Scotland.', '["A. by","B. with","C. at","D. from"]', 'A', 'Câu bị động tác nhân con người: ''written by''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_536', 'lop_7', 'van_dung_cao', 'published', 'grammar', 'Have you ever ________ to Singapore? -> Yes, twice.', '["A. been","B. gone","C. went","D. be"]', 'A', 'Từng đến đâu rồi trở về: ''Have you ever been to...''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_537', 'lop_7', 'nhan_biet', 'published', 'vocabulary', 'Can I try this shirt on? -> Yes, the changing rooms are over ________.', '["A. there","B. their","C. they''re","D. here it"]', 'A', 'Phòng thay đồ ở đằng kia: ''over there''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_538', 'lop_7', 'thong_hieu', 'published', 'grammar', 'She is much ________ at mathematics than her twin brother.', '["A. better","B. good","C. best","D. more good"]', 'A', 'So sánh hơn của good là ''better than''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_539', 'lop_7', 'van_dung', 'published', 'grammar', 'You ________ touch that hot stove; you will burn your fingers!', '["A. mustn''t","B. needn''t","C. should","D. can"]', 'A', 'Cấm chỉ đoán tai nạn nguy hiểm: ''mustn''t''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_540', 'lop_7', 'van_dung_cao', 'published', 'vocabulary', 'The doctor advised him to take regular exercise and drink plenty of ________.', '["A. water","B. soda","C. coffee","D. wine"]', 'A', 'Uống nhiều nước lọc tốt cho sức khỏe: ''water''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_541', 'lop_7', 'nhan_biet', 'published', 'grammar', 'There are thirty students in our class, ________ of whom are girls.', '["A. half","B. two","C. double","D. piece"]', 'A', 'Một nửa trong số đó là học sinh nữ: ''half of whom''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_542', 'lop_7', 'thong_hieu', 'published', 'grammar', 'Rewrite test: ''I haven''t seen Linda for five months.'' -> ''The last time I saw Linda was...''', '["A. five months ago.","B. since five months.","C. for five months.","D. in five months ago."]', 'A', 'Chuyển từ hiện tại hoàn thành phủ định sang ''The last time... was... ago''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_543', 'lop_7', 'van_dung', 'published', 'grammar', 'Would you like a cup of green tea? -> ________, I''d prefer a glass of cold water.', '["A. No, thank you","B. Yes, please","C. Sure, why not","D. Of course"]', 'A', 'Từ chối lời mời lịch sự: ''No, thank you''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_544', 'lop_7', 'van_dung_cao', 'published', 'vocabulary', 'The university library has a vast collection of academic journals ________ to all enrolled students.', '["A. accessible","B. access","C. accessed","D. accessibility"]', 'A', 'Tính từ ''accessible to'' (có thể tiếp cận được đối với).', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_545', 'lop_7', 'nhan_biet', 'published', 'grammar', 'If you hadn''t reminded me, I ________ forgotten all about the deadline.', '["A. would have","B. will have","C. had","D. would"]', 'A', 'Điều kiện loại 3: If + S + had V3, S + would have + V3.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_546', 'lop_7', 'thong_hieu', 'published', 'vocabulary', 'The newly appointed manager decided to ________ changes to the shift schedule.', '["A. introduce","B. do","C. take","D. make up"]', 'A', 'Đưa ra/áp dụng các thay đổi: ''introduce changes''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_547', 'lop_7', 'van_dung', 'published', 'vocabulary', 'Although she was nervous before the presentation, she ________ it off successfully.', '["A. carried","B. made","C. did","D. brought"]', 'A', 'Cụm thành công vượt qua thử thách khó khăn: ''carry it off''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_548', 'lop_7', 'van_dung_cao', 'published', 'vocabulary', 'The ancient ruins attracted archaeological experts from all ________ the globe.', '["A. over","B. across","C. around","D. through"]', 'A', 'Cụm ''all over the globe'' (khắp toàn cầu).', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_549', 'lop_7', 'nhan_biet', 'published', 'grammar', 'Rewrite test: ''They are building a modern sports complex near the university.'' -> ''A modern sports complex...''', '["A. is being built near the university.","B. was built near the university.","C. is built near the university.","D. has built near the university."]', 'A', 'Bị động thì hiện tại tiếp diễn: ''is being built''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_550', 'lop_7', 'thong_hieu', 'published', 'vocabulary', 'We should make sure to set off early to avoid getting stuck in the morning rush ________.', '["A. hour","B. time","C. period","D. minute"]', 'A', 'Giờ cao điểm giao thông: ''rush hour''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_551', 'lop_7', 'van_dung', 'published', 'grammar', 'The teacher encouraged her pupils ________ actively in group discussions.', '["A. to participate","B. participate","C. participating","D. participated"]', 'A', 'Cấu trúc encourage someone to V: ''to participate''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_552', 'lop_7', 'van_dung_cao', 'published', 'grammar', 'Rewrite test: ''I suggest taking a taxi because it''s pouring outside.'' -> ''Why don''t we...''', '["A. take a taxi because it''s pouring outside?","B. taking a taxi because it''s pouring outside?","C. to take a taxi because it''s pouring outside?","D. took a taxi because it''s pouring outside?"]', 'A', 'Biến đổi cấu trúc gợi ý: suggest V-ing -> Why don''t we + V nguyên mẫu?', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_553', 'lop_7', 'nhan_biet', 'published', 'vocabulary', 'Unless emergency repairs are carried ________ promptly, the bridge may collapse.', '["A. out","B. on","C. off","D. in"]', 'A', 'Tiến hành thực hiện sửa chữa: ''carried out''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_554', 'lop_7', 'thong_hieu', 'published', 'grammar', 'The committee consists ________ ten distinguished professors in education.', '["A. of","B. in","C. with","D. for"]', 'A', 'Bao gồm, gồm có: ''consist of''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_555', 'lop_7', 'van_dung', 'published', 'grammar', 'He apologized to his colleagues ________ having missed the quarterly briefing.', '["A. for","B. about","C. with","D. on"]', 'A', 'Xin lỗi vì điều gì: ''apologize for + V-ing''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_556', 'lop_7', 'van_dung_cao', 'published', 'vocabulary', 'The novel was so thrilling that she finished reading it in a single ________.', '["A. sitting","B. standing","C. lying","D. staying"]', 'A', 'Đọc liền một mạch: ''in a single sitting''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_557', 'lop_7', 'nhan_biet', 'published', 'grammar', 'Rewrite test: ''Nobody in my class speaks Spanish better than Maria.'' -> ''Maria speaks Spanish...''', '["A. the best in my class.","B. better than anyone in my class.","C. as well as nobody in my class.","D. good in my class."]', 'A', 'So sánh nhất chuyển từ so sánh hơn phủ định.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_558', 'lop_7', 'thong_hieu', 'published', 'grammar', 'I really appreciate your helping hand during the school festival! -> ________', '["A. It was my pleasure, anytime!","B. No thanks.","C. Yes, please.","D. Never mind."]', 'A', 'Đáp lại lời cảm ơn một cách thân thiện, nhiệt tình.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_559', 'lop_7', 'van_dung', 'published', 'reading', 'Passage statement: ''Solar installations expanded by 45% in 2024.'' Question: Solar energy saw unprecedented growth recently. -> ________', '["A. TRUE","B. FALSE","C. NOT GIVEN","D. NONE"]', 'A', 'Đoạn văn xác nhận mức tăng 45% chứng minh sự phát triển chưa từng có -> TRUE.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_560', 'lop_7', 'van_dung_cao', 'published', 'reading', 'Passage statement: ''The researchers examined 50 coral species.'' Question: All coral species will recover within a decade. -> ________', '["A. NOT GIVEN","B. TRUE","C. FALSE","D. NONE"]', 'A', 'Bài viết không hề khẳng định toàn bộ loài san hô sẽ phục hồi trong 10 năm -> NOT GIVEN.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_561', 'lop_7', 'nhan_biet', 'published', 'vocabulary', 'The policy was introduced with the overarching aim of ________ socio-economic disparities.', '["A. mitigating","B. increasing","C. aggravating","D. celebrating"]', 'A', 'Giảm thiểu, làm nhẹ bớt sự chênh lệch kinh tế xã hội: ''mitigating disparities''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_562', 'lop_7', 'thong_hieu', 'published', 'vocabulary', 'The empirical findings corroborate the initial hypothesis. -> ''Corroborate'' is CLOSEST in meaning to: ________', '["A. confirm","B. contradict","C. dismiss","D. reject"]', 'A', '''corroborate'' đồng nghĩa với ''confirm'' (chứng thực, củng cố tính đúng đắn).', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_563', 'lop_7', 'van_dung', 'published', 'vocabulary', 'Industrial effluent discharged into marine ecosystems poses a ________ threat to aquatic organisms.', '["A. grave","B. minor","C. pleasant","D. gentle"]', 'A', 'Mối đe dọa nghiêm trọng: ''grave threat''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_564', 'lop_7', 'van_dung_cao', 'published', 'vocabulary', 'Governments must impose stringent regulations to curb the rampant ________ of natural resources.', '["A. depletion","B. creation","C. generation","D. production"]', 'A', 'Sự suy kiệt cạn kiệt tài nguyên thiên nhiên: ''depletion''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_565', 'lop_7', 'nhan_biet', 'published', 'grammar', 'The sudden influx of tourists placed an unsustainable strain ________ the island''s fragile infrastructure.', '["A. on","B. in","C. at","D. with"]', 'A', 'Gây áp lực nặng nề lên điều gì: ''place a strain on''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_566', 'lop_7', 'thong_hieu', 'published', 'grammar', 'Not only ________ carbon emissions, but electric vehicles also significantly reduce noise pollution.', '["A. do they diminish","B. they diminish","C. they do diminish","D. did they diminish"]', 'A', 'Đảo ngữ với ''Not only'': trợ động từ ''do'' + they + V nguyên mẫu.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_567', 'lop_7', 'van_dung', 'published', 'reading', 'The author''s tone throughout the academic treatise can best be described as ________.', '["A. objective and analytical","B. sarcastic and cynical","C. emotional and biassed","D. indifferent"]', 'A', 'Văn phong học thuật chuẩn mực luôn khách quan và mang tính phân tích: ''objective and analytical''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_568', 'lop_7', 'van_dung_cao', 'published', 'vocabulary', 'Urbanisation has precipitated an unprecedented surge in demand for affordable ________.', '["A. housing","B. house","C. housed","D. houser"]', 'A', 'Nhà ở giá cả phải chăng: ''affordable housing''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_569', 'lop_7', 'nhan_biet', 'published', 'vocabulary', 'The new vaccine demonstrated exceptional efficacy in ________ clinical trials.', '["A. rigorous","B. careless","C. superficial","D. randomless"]', 'A', 'Các thử nghiệm lâm sàng nghiêm ngặt chặt chẽ: ''rigorous clinical trials''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_570', 'lop_7', 'thong_hieu', 'published', 'grammar', 'Had the regulatory authorities acted with greater urgency, the ecological catastrophe ________ averted.', '["A. might have been","B. might be","C. was","D. will be"]', 'A', 'Đảo ngữ câu điều kiện loại 3 dạng bị động: ''might have been averted''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_571', 'lop_7', 'van_dung', 'published', 'vocabulary', 'Academic writing requires students to synthesise diverse perspectives and avoid ________ reasoning.', '["A. fallacious","B. logical","C. sound","D. coherent"]', 'A', 'Lập luận ngụy biện, sai lệch: ''fallacious reasoning''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_572', 'lop_7', 'van_dung_cao', 'published', 'vocabulary', 'The ubiquitous presence of microplastics in drinking water warrants urgent international ________.', '["A. intervention","B. neglect","C. disregard","D. hesitation"]', 'A', 'Đòi hỏi sự can thiệp cấp thiết quốc tế: ''international intervention''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_573', 'lop_7', 'nhan_biet', 'published', 'vocabulary', 'To recapitulate, addressing climate change necessitates a paradigm ________ in global energy consumption.', '["A. shift","B. move","C. turn","D. step"]', 'A', 'Sự thay đổi căn bản trong nhận thức và phương thức (bước chuyển hình thái): ''paradigm shift''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_sup_g7_phonics_1', 'lop_7', 'nhan_biet', 'published', 'phonics', 'Choose the word with different pronunciation of the underlined part: h<u>ea</u>d, br<u>ea</u>d, cl<u>ea</u>n, h<u>ea</u>vy', '["A. head","B. bread","C. clean","D. heavy"]', 'C', 'clean has /i:/ while others have /e/', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_sup_g7_phonics_2', 'lop_7', 'thong_hieu', 'published', 'phonics', 'Choose the word whose underlined part is pronounced differently: look<u>ed</u>, watch<u>ed</u>, carri<u>ed</u>, stopp<u>ed</u>', '["A. looked","B. watched","C. carried","D. stopped"]', 'C', 'carried has /d/ while others have /t/', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_sup_g7_phonics_3', 'lop_7', 'van_dung', 'published', 'phonics', 'Choose the word whose stress pattern is different from the others: intend, decide, happen, agree', '["A. intend","B. decide","C. happen","D. agree"]', 'C', 'happen has stress on 1st syllable, others on 2nd', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_sup_g7_phonics_4', 'lop_7', 'van_dung_cao', 'published', 'phonics', 'Choose the word whose stress is placed differently: economic, Vietnamese, celebration, category', '["A. economic","B. Vietnamese","C. celebration","D. category"]', 'D', 'category has stress on 1st syllable', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_sup_g7_phonics_5', 'lop_7', 'nhan_biet', 'published', 'phonics', 'Choose the word with different pronunciation of the underlined part: h<u>ea</u>d, br<u>ea</u>d, cl<u>ea</u>n, h<u>ea</u>vy', '["A. head","B. bread","C. clean","D. heavy"]', 'C', 'clean has /i:/ while others have /e/', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_sup_g7_phonics_6', 'lop_7', 'thong_hieu', 'published', 'phonics', 'Choose the word whose underlined part is pronounced differently: look<u>ed</u>, watch<u>ed</u>, carri<u>ed</u>, stopp<u>ed</u>', '["A. looked","B. watched","C. carried","D. stopped"]', 'C', 'carried has /d/ while others have /t/', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_sup_g7_reading_1', 'lop_7', 'nhan_biet', 'published', 'reading', 'According to the passage, why do students need to practice reading every day?', '["A. To improve vocabulary and reading speed","B. To pass exams only","C. Because teachers force them","D. To play more games"]', 'A', 'Daily reading enhances both vocabulary comprehension and processing speed.', 'Reading is one of the most effective habits to acquire a second language naturally. When learners expose themselves to various texts daily, they encounter recurring patterns and rich contexts that solidify long-term retention.');
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_sup_g7_reading_2', 'lop_7', 'thong_hieu', 'published', 'reading', 'What is the main topic of the reading text?', '["A. Modern communication technologies","B. The importance of daily reading habits","C. History of English grammar","D. Tips for writing essays"]', 'B', 'The central theme focuses on the role of consistent reading habits in language mastery.', 'Reading is one of the most effective habits to acquire a second language naturally. When learners expose themselves to various texts daily, they encounter recurring patterns and rich contexts that solidify long-term retention.');
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_sup_g7_reading_3', 'lop_7', 'van_dung', 'published', 'reading', 'The word "solidify" in the passage is closest in meaning to:', '["A. weaken","B. strengthen","C. eliminate","D. doubt"]', 'B', 'Solidify means to make something stronger and more definite.', 'Reading is one of the most effective habits to acquire a second language naturally. When learners expose themselves to various texts daily, they encounter recurring patterns and rich contexts that solidify long-term retention.');
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_sup_g7_reading_4', 'lop_7', 'van_dung_cao', 'published', 'reading', 'Which of the following is NOT true according to the passage?', '["A. Daily reading expands vocabulary","B. Texts provide rich contexts","C. Reading makes learners forget patterns","D. Reading supports long-term retention"]', 'C', 'The passage explicitly states reading solidifies patterns, rather than forgetting them.', 'Reading is one of the most effective habits to acquire a second language naturally. When learners expose themselves to various texts daily, they encounter recurring patterns and rich contexts that solidify long-term retention.');
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_sup_g7_reading_5', 'lop_7', 'nhan_biet', 'published', 'reading', 'According to the passage, why do students need to practice reading every day?', '["A. To improve vocabulary and reading speed","B. To pass exams only","C. Because teachers force them","D. To play more games"]', 'A', 'Daily reading enhances both vocabulary comprehension and processing speed.', 'Reading is one of the most effective habits to acquire a second language naturally. When learners expose themselves to various texts daily, they encounter recurring patterns and rich contexts that solidify long-term retention.');
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_sup_g7_reading_6', 'lop_7', 'thong_hieu', 'published', 'reading', 'What is the main topic of the reading text?', '["A. Modern communication technologies","B. The importance of daily reading habits","C. History of English grammar","D. Tips for writing essays"]', 'B', 'The central theme focuses on the role of consistent reading habits in language mastery.', 'Reading is one of the most effective habits to acquire a second language naturally. When learners expose themselves to various texts daily, they encounter recurring patterns and rich contexts that solidify long-term retention.');
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_sup_g9_vocabulary_1', 'lop_9', 'nhan_biet', 'published', 'vocabulary', 'She made a significant _______ to the success of our community outreach project.', '["A. contribute","B. contribution","C. contributor","D. contributive"]', 'B', 'After an adjective (significant), a noun is required (contribution).', NULL);
