INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_sup_g9_reading_1', 'lop_9', 'nhan_biet', 'published', 'reading', 'According to the passage, why do students need to practice reading every day?', '["A. To improve vocabulary and reading speed","B. To pass exams only","C. Because teachers force them","D. To play more games"]', 'A', 'Daily reading enhances both vocabulary comprehension and processing speed.', 'Reading is one of the most effective habits to acquire a second language naturally. When learners expose themselves to various texts daily, they encounter recurring patterns and rich contexts that solidify long-term retention.');
