INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_sup_g9_reading_3', 'lop_9', 'van_dung', 'published', 'reading', 'The word "solidify" in the passage is closest in meaning to:', '["A. weaken","B. strengthen","C. eliminate","D. doubt"]', 'B', 'Solidify means to make something stronger and more definite.', 'Reading is one of the most effective habits to acquire a second language naturally. When learners expose themselves to various texts daily, they encounter recurring patterns and rich contexts that solidify long-term retention.');
