INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_sup_g12_phonics_14', 'lop_12', 'thong_hieu', 'published', 'phonics', 'Choose the word whose underlined part is pronounced differently: look<u>ed</u>, watch<u>ed</u>, carri<u>ed</u>, stopp<u>ed</u>', '["A. looked","B. watched","C. carried","D. stopped"]', 'C', 'carried has /d/ while others have /t/', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_sup_g12_reading_1', 'lop_12', 'nhan_biet', 'published', 'reading', 'According to the passage, why do students need to practice reading every day?', '["A. To improve vocabulary and reading speed","B. To pass exams only","C. Because teachers force them","D. To play more games"]', 'A', 'Daily reading enhances both vocabulary comprehension and processing speed.', 'Reading is one of the most effective habits to acquire a second language naturally. When learners expose themselves to various texts daily, they encounter recurring patterns and rich contexts that solidify long-term retention.');
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_sup_g12_reading_2', 'lop_12', 'thong_hieu', 'published', 'reading', 'What is the main topic of the reading text?', '["A. Modern communication technologies","B. The importance of daily reading habits","C. History of English grammar","D. Tips for writing essays"]', 'B', 'The central theme focuses on the role of consistent reading habits in language mastery.', 'Reading is one of the most effective habits to acquire a second language naturally. When learners expose themselves to various texts daily, they encounter recurring patterns and rich contexts that solidify long-term retention.');
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_sup_g12_reading_3', 'lop_12', 'van_dung', 'published', 'reading', 'The word "solidify" in the passage is closest in meaning to:', '["A. weaken","B. strengthen","C. eliminate","D. doubt"]', 'B', 'Solidify means to make something stronger and more definite.', 'Reading is one of the most effective habits to acquire a second language naturally. When learners expose themselves to various texts daily, they encounter recurring patterns and rich contexts that solidify long-term retention.');
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_sup_g12_reading_4', 'lop_12', 'van_dung_cao', 'published', 'reading', 'Which of the following is NOT true according to the passage?', '["A. Daily reading expands vocabulary","B. Texts provide rich contexts","C. Reading makes learners forget patterns","D. Reading supports long-term retention"]', 'C', 'The passage explicitly states reading solidifies patterns, rather than forgetting them.', 'Reading is one of the most effective habits to acquire a second language naturally. When learners expose themselves to various texts daily, they encounter recurring patterns and rich contexts that solidify long-term retention.');
