INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_1_g7alt', '7', 'nhan_biet', 'published', 'phonics', 'Choose the word whose underlined part is pronounced differently: c<u>oa</u>ch, c<u>a</u>re, d<u>e</u>cide, sc<u>a</u>red', '["A. coach","B. care","C. decide","D. scared"]', 'C', 'Đáp án C: chữ ''c'' trong ''decide'' phát âm là /s/, trong khi ''coach'', ''care'', ''scared'' đều phát âm là /k/.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_2_g7alt', '7', 'thong_hieu', 'published', 'phonics', 'Choose the word whose underlined part is pronounced differently: r<u>ea</u>lize, r<u>ea</u>der, s<u>ea</u>son, ov<u>er</u>seas', '["A. realize","B. reader","C. season","D. overseas"]', 'A', 'Đáp án A: ''ea'' trong ''realize'' phát âm là nguyên âm đôi /ɪə/ (/ˈrɪəlaɪz/), còn ''reader'', ''season'', ''overseas'' đều phát âm là nguyên âm dài /iː/.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_3_g7alt', '7', 'van_dung', 'published', 'phonics', 'Choose the word whose -ed pronounced differently: nak<u>ed</u>, intend<u>ed</u>, wretch<u>ed</u>, plough<u>ed</u>', '["A. naked","B. intended","C. wretched","D. ploughed"]', 'D', 'Đáp án D: ''ploughed'' phát âm đuôi -ed là /d/ (/plaʊd/). Các từ ''naked'' /ˈneɪkɪd/, ''intended'' /ɪnˈtendɪd/, ''wretched'' /ˈretʃɪd/ đều phát âm đuôi -ed là /ɪd/.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_4_g7alt', '7', 'van_dung_cao', 'published', 'phonics', 'Choose the word whose stress pattern is different: telephone, directory, computer, appliance', '["A. telephone","B. directory","C. computer","D. appliance"]', 'A', 'Đáp án A: ''telephone'' có trọng âm rơi vào âm tiết 1 (TE-le-phone /ˈtelɪfəʊn/), ba từ còn lại đều có trọng âm rơi vào âm tiết 2: di-REC-tory, com-PU-ter, ap-PLI-ance.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_5_g7alt', '7', 'nhan_biet', 'published', 'phonics', 'Choose the word whose stress pattern is different: affect, affirm, study, collapse', '["A. affect","B. affirm","C. study","D. collapse"]', 'C', 'Đáp án C: ''study'' là động từ 2 âm tiết có trọng âm rơi vào âm 1 (STU-dy /ˈstʌdi/). Ba từ còn lại đều có trọng âm rơi vào âm 2: af-FECT, af-FIRM, col-LAPSE.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_6_g7alt', '7', 'thong_hieu', 'published', 'vocabulary', 'Wave energy is a source of ______ energy.', '["A. environment friendly","B. environmental friendly","C. environmentally friendly","D. environmentally friendliness"]', 'C', 'Đáp án C: Cụm tính từ ghép ''environmentally friendly'' (trạng từ + tính từ) có nghĩa là thân thiện với môi trường.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_7_g7alt', '7', 'van_dung', 'published', 'vocabulary', 'Do you want to know how you can ______ healthy?', '["A. make","B. have","C. stay","D. create"]', 'C', 'Đáp án C: Cụm cố định ''stay healthy'' có nghĩa là giữ gìn sức khỏe / sống khỏe mạnh.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_8_g7alt', '7', 'van_dung_cao', 'published', 'grammar', 'Linh often uses her headphones when listening to music ______ her parents don''t like loud noise.', '["A. so","B. but","C. because","D. and"]', 'C', 'Đáp án C: Mệnh đề sau chỉ nguyên nhân lý do (''her parents don''t like loud noise'') -> dùng liên từ ''because''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_9_g7alt', '7', 'nhan_biet', 'published', 'vocabulary', '______, many teenagers say they don''t like football - one of the world''s most popular games.', '["A. Surprise","B. Surprising","C. Surprisingly","D. Surprised"]', 'C', 'Đáp án C: Dùng trạng từ đứng đầu câu trước dấu phẩy để bổ nghĩa cho cả câu (''Surprisingly'' = Thật đáng ngạc nhiên là).', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_10_g7alt', '7', 'thong_hieu', 'published', 'vocabulary', 'You should pay more ______ in class to understand the lesson thoroughly.', '["A. part","B. care","C. notice","D. attention"]', 'D', 'Đáp án D: Cụm thành ngữ ''pay attention to'' có nghĩa là chú ý, tập trung.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_11_g7alt', '7', 'van_dung', 'published', 'vocabulary', 'My mother worries who will ______ our house when we are away for our summer holidays.', '["A. see","B. take after","C. take care of","D. look at"]', 'C', 'Đáp án C: ''take care of'' = chăm sóc, trông nom nhà cửa khi đi vắng.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_12_g7alt', '7', 'van_dung_cao', 'published', 'grammar', 'Wearing a band over the wrist allows players ______ safely.', '["A. playing","B. to play","C. play","D. plays"]', 'B', 'Đáp án B: Cấu trúc ''allow somebody TO V'' (cho phép ai làm gì) -> to play.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_13_g7alt', '7', 'nhan_biet', 'published', 'vocabulary', 'In my opinion, nuclear power is not only expensive but also ______ to our living environment.', '["A. danger","B. dangerous","C. risk","D. disaster"]', 'B', 'Đáp án B: Sau ''be'' và song hành với tính từ ''expensive'' trong cấu trúc ''not only... but also...'', ta cần tính từ ''dangerous''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_14_g7alt', '7', 'thong_hieu', 'published', 'vocabulary', 'It''s considered very rude to ______ poorer people in the community.', '["A. look up to","B. look after","C. look down on","D. look for"]', 'C', 'Đáp án C: Cụm động từ ''look down on'' có nghĩa là coi thường, khinh miệt.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_15_g7alt', '7', 'van_dung', 'published', 'grammar', '______ extremely tired after the long journey, I went straight to bed last night.', '["A. Felt","B. Feeling","C. To feel","D. Feel"]', 'B', 'Đáp án B: Mệnh đề phân từ hiện tại (Present Participle Clause ''Feeling'') rút gọn từ ''Because I felt extremely tired...''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_16_g7alt', '7', 'van_dung_cao', 'published', 'grammar', '______ is the hottest planet in the solar system with surface temperatures exceeding 460°C.', '["A. Mercury","B. Venus","C. Mars","D. Uranus"]', 'B', 'Đáp án B: Sao Kim (Venus) là hành tinh nóng nhất trong hệ mặt trời do hiệu ứng nhà kính dày đặc từ khí CO2.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_17_g7alt', '7', 'nhan_biet', 'published', 'grammar', 'The younger you are, ______ it is to acquire natural native-like pronunciation.', '["A. easier","B. the easier","C. easily","D. the easily"]', 'B', 'Đáp án B: Cấu trúc so sánh kép (The + comparative, the + comparative) -> the easier.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_31_g7alt', '7', 'van_dung', 'published', 'phonics', 'Find the word which has a different sound in the underlined part: w<u>a</u>sh, w<u>a</u>rm, w<u>a</u>ll, w<u>a</u>lk', '["A. wash","B. warm","C. wall","D. walk"]', 'A', 'Đáp án A: ''wash'' phát âm là /ɒ/ (hoặc /ɑː/ trong Anh-Mỹ), còn ''warm'', ''wall'', ''walk'' đều phát âm là nguyên âm dài /ɔː/.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_32_g7alt', '7', 'van_dung_cao', 'published', 'phonics', 'Find the word which has a different sound in the underlined part: p<u>a</u>n, b<u>a</u>g, w<u>a</u>ter, <u>a</u>dd', '["A. pan","B. bag","C. water","D. add"]', 'C', 'Đáp án C: ''water'' phát âm là /ɔː/ (/ˈwɔːtər/), trong khi ''pan'', ''bag'', ''add'' đều phát âm là nguyên âm bẹt /æ/.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_41_g7alt', '7', 'nhan_biet', 'published', 'phonics', 'Choose the word whose underlined part is pronounced differently: c<u>oa</u>ch, c<u>a</u>re, d<u>e</u>cide, sc<u>a</u>red', '[]', 'C', 'Đáp án C: chữ ''c'' trong ''decide'' phát âm là /s/, còn trong ''coach'', ''care'', ''scared'' phát âm là /k/.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_42_g7alt', '7', 'thong_hieu', 'published', 'phonics', 'Choose the word with stress placed differently from the others: perform, gather, review, attract', '[]', 'B', 'Đáp án B: ''gather'' /ˈɡæðər/ có trọng âm rơi vào âm tiết 1; các từ còn lại đều có trọng âm rơi vào âm tiết 2 (/pəˈfɔːm/, /rɪˈvjuː/, /əˈtrækt/).', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_43_g7alt', '7', 'van_dung', 'published', 'vocabulary', 'The government is trying to encourage people to use _______ sources of energy such as wind and solar.', '[]', 'A', 'Đáp án A: ''renewable energy'' (năng lượng tái tạo) gồm năng lượng gió (wind) và mặt trời (solar).', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_44_g7alt', '7', 'van_dung_cao', 'published', 'grammar', 'My mother used to _______ a small red bicycle when she was a student.', '[]', 'B', 'Đáp án B: Cấu trúc thói quen quá khứ: used to + V_nguyên thể (ride).', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_45_g7alt', '7', 'nhan_biet', 'published', 'grammar', 'Choose the correct sentence transformation: ''She started learning English 5 years ago.''', '[]', 'A', 'Đáp án A: Chuyển đổi thì Quá khứ đơn ''started V-ing ... ago'' sang Hiện tại hoàn thành ''have/has V3/ed for ...''.', NULL);
