INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_379_g7alt', '7', 'van_dung', 'published', 'phonics', 'Which word has the underlined part pronounced as /ɜː/?', '["A. b<u>i</u>rd","B. <u>a</u>bout","C. doct<u>o</u>r","D. teach<u>e</u>r"]', 'A', '''bird'' phát âm là /ɜː/, các từ còn lại phát âm là /ə/.', NULL);
