INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_382_g7alt', '7', 'thong_hieu', 'published', 'vocabulary', 'We should donate old warm clothes to ________ children in remote areas.', '["A. underprivileged","B. wealthy","C. rich","D. lucky"]', 'A', 'Trẻ em có hoàn cảnh khó khăn: ''underprivileged children''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_383_g7alt', '7', 'van_dung', 'published', 'grammar', 'Eat more vegetables ________ they provide essential vitamins.', '["A. because","B. although","C. but","D. so"]', 'A', 'Liên từ chỉ nguyên nhân: ''because'' (bởi vì).', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_504_g7alt', '7', 'van_dung_cao', 'published', 'reading', 'Notice: ''Please keep off the grass!'' -> What does this mean?', '["A. Do not walk on the grass","B. You can play football on the grass","C. Cut the grass now","D. Water the grass"]', 'A', 'Biển báo ''Keep off the grass'' nghĩa là không được giẫm lên cỏ.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_505_g7alt', '7', 'nhan_biet', 'published', 'reading', 'Notice: ''Buy one coffee, get one free before 9:00 AM!'' -> What does this mean?', '["A. Morning coffee is cheaper","B. Coffee is served only at 9:00 AM","C. You cannot buy coffee in the morning","D. Coffee is free all day"]', 'A', 'Mua 1 tặng 1 trước 9h nghĩa là cà phê buổi sáng rẻ hơn.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_506_g7alt', '7', 'thong_hieu', 'published', 'vocabulary', 'I need to buy a return train ________ to Oxford.', '["A. ticket","B. book","C. letter","D. stamp"]', 'A', 'Vé tàu khứ hồi: ''return train ticket''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_507_g7alt', '7', 'van_dung', 'published', 'vocabulary', 'Can you help me ________ my lost luggage at the airport counter?', '["A. find","B. look","C. see","D. watch"]', 'A', 'Tìm hành lý thất lạc: ''find my lost luggage''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_508_g7alt', '7', 'van_dung_cao', 'published', 'vocabulary', 'The museum admission fee is ________ for children under 6 years old.', '["A. free","B. expensive","C. costly","D. high"]', 'A', 'Miễn phí cho trẻ em: ''free''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_509_g7alt', '7', 'nhan_biet', 'published', 'reading', 'Email notice: ''Library renovation: The second floor will remain closed until Friday.'' What does this mean?', '["A. Students cannot access second floor books before Friday.","B. The entire library is closed forever.","C. Renovation starts on Friday.","D. The first floor is closed."]', 'A', 'Tầng 2 đóng cửa sửa chữa tới thứ Sáu nghĩa là học sinh không thể vào tầng 2 trước thứ Sáu.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_510_g7alt', '7', 'thong_hieu', 'published', 'grammar', 'He is really keen ________ learning digital photography and photo editing.', '["A. on","B. in","C. at","D. with"]', 'A', 'Cụm ''keen on + V-ing'' (say mê, thích thú).', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_511_g7alt', '7', 'van_dung', 'published', 'vocabulary', 'Although it rained cats and dogs, the outdoor music concert was not ________ off.', '["A. called","B. put","C. taken","D. made"]', 'A', 'Hủy bỏ buổi hòa nhạc: ''called off''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_512_g7alt', '7', 'van_dung_cao', 'published', 'grammar', 'The hotel staff apologized for the unexpected delay in ________ our room.', '["A. preparing","B. prepare","C. prepared","D. preparation"]', 'A', 'Sau giới từ in dùng V-ing: ''preparing''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_513_g7alt', '7', 'nhan_biet', 'published', 'grammar', 'She managed to solve the challenging crossword puzzle entirely on her ________.', '["A. own","B. self","C. single","D. alone"]', 'A', 'Cụm tự mình làm không cần trợ giúp: ''on her own''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_514_g7alt', '7', 'thong_hieu', 'published', 'vocabulary', 'Governments should allocate substantial funding to ________ medical research on infectious diseases.', '["A. expedite","B. slow","C. delay","D. hinder"]', 'A', 'Thúc đẩy nhanh tiến độ nghiên cứu: ''expedite medical research''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_515_g7alt', '7', 'van_dung', 'published', 'vocabulary', 'Deforestation contributes significantly to biodiversity loss, thereby ________ vulnerable wildlife populations.', '["A. jeopardizing","B. safe","C. securing","D. nurturing"]', 'A', 'Đe dọa, đặt vào vòng hiểm nguy: ''jeopardizing vulnerable populations''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_516_g7alt', '7', 'van_dung_cao', 'published', 'vocabulary', 'Urban planners must adopt sustainable practices to ________ with the demands of rapid population influx.', '["A. cope","B. meet","C. lead","D. stand"]', 'A', 'Đương đầu và thích nghi với thách thức: ''cope with demands''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_517_g7alt', '7', 'nhan_biet', 'published', 'vocabulary', 'There is compelling empirical evidence demonstrating the ________ correlation between regular exercise and longevity.', '["A. positive","B. hostile","C. negative","D. false"]', 'A', 'Mối tương quan đồng thuận tích cực: ''positive correlation''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_518_g7alt', '7', 'thong_hieu', 'published', 'vocabulary', 'Proponents argue that artificial intelligence will ________ unprecedented productivity across global economies.', '["A. catalyze","B. freeze","C. abolish","D. dampen"]', 'A', 'Xúc tác, thúc đẩy mạnh mẽ: ''catalyze productivity''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_519_g7alt', '7', 'van_dung', 'published', 'reading', 'Notice: ''Swimming pool closed for water treatment from 1:00 PM to 3:00 PM.'' What is true?', '["A. You cannot swim between 1:00 PM and 3:00 PM.","B. The pool is open all day.","C. The pool is closed at night.","D. Swimming is free today."]', 'A', 'Hồ bơi đóng cửa xử lý nước từ 1h đến 3h chiều -> không được bơi trong khoảng thời gian này.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_520_g7alt', '7', 'van_dung_cao', 'published', 'reading', 'Sign on bus door: ''Have exact change ready before boarding.'' What does the driver want?', '["A. Passengers to prepare the correct coins or notes in advance.","B. Passengers to pay after arriving.","C. Passengers to buy bus tickets online.","D. Passengers to travel for free."]', 'A', '''Exact change'' nghĩa là chuẩn bị sẵn tiền lẻ đúng số tiền vé trước khi lên xe.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_521_g7alt', '7', 'nhan_biet', 'published', 'grammar', 'What time does the film start? -> ________ 7:30 PM.', '["A. At","B. In","C. On","D. For"]', 'A', 'Giờ giấc đi với giới từ ''At''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_522_g7alt', '7', 'thong_hieu', 'published', 'vocabulary', 'I can''t go cycling today because my bicycle tire is ________.', '["A. flat","B. heavy","C. sharp","D. sweet"]', 'A', 'Lốp xe đạp bị xẹp/thủng: ''flat tire''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_523_g7alt', '7', 'van_dung', 'published', 'grammar', 'Could you please tell me the way to the railway station? -> ________', '["A. Turn right at the traffic lights, it''s opposite the post office.","B. Yes, I do.","C. No, I am fine.","D. It is five dollars."]', 'A', 'Chỉ đường lịch sự trong giao tiếp tiếng Anh KET.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_524_g7alt', '7', 'van_dung_cao', 'published', 'grammar', 'She is really looking forward to ________ her pen pal in London this summer.', '["A. meeting","B. meet","C. met","D. to meet"]', 'A', 'Cấu trúc look forward to + V-ing: ''meeting''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_525_g7alt', '7', 'nhan_biet', 'published', 'grammar', 'We didn''t go on a picnic yesterday ________ the heavy downpour.', '["A. because of","B. because","C. although","D. despite of"]', 'A', 'Because of + cụm danh từ ''the heavy downpour''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_526_g7alt', '7', 'thong_hieu', 'published', 'grammar', 'Excuse me, how much is this souvenir postcard? -> ________', '["A. It''s one pound fifty.","B. It''s blue.","C. It''s on the table.","D. It''s very tall."]', 'A', 'Hỏi giá tiền: ''It''s one pound fifty.''', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_527_g7alt', '7', 'van_dung', 'published', 'grammar', 'My brother is fond of ________ old postage stamps and coins.', '["A. collecting","B. collect","C. collected","D. collects"]', 'A', 'Sau cụm tính từ fond of dùng V-ing: ''collecting''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_528_g7alt', '7', 'van_dung_cao', 'published', 'vocabulary', 'What would you like for dessert? -> A slice of chocolate ________, please.', '["A. cake","B. meat","C. soup","D. rice"]', 'A', 'Món tráng miệng là bánh socola -> ''cake''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_529_g7alt', '7', 'nhan_biet', 'published', 'reading', 'Notice in computer lab: ''Do not eat or drink near keyboards.'' Why?', '["A. To protect computer equipment from liquid damage.","B. Keyboards are made of food.","C. Food is sold in the lab.","D. Students must eat quickly."]', 'A', 'Bảo vệ bàn phím máy tính khỏi bị đổ nước làm hỏng.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_530_g7alt', '7', 'thong_hieu', 'published', 'reading', 'Sign in museum: ''Photography permitted without flash.'' What can visitors do?', '["A. Take photos without using flash.","B. Take photos with bright flash only.","C. No cameras allowed at all.","D. Buy pictures from the gift shop."]', 'A', 'Được phép chụp ảnh nhưng không được dùng đèn flash.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_531_g7alt', '7', 'van_dung', 'published', 'grammar', 'He ________ English since he was six years old.', '["A. has studied","B. studied","C. studies","D. is studying"]', 'A', 'Dấu hiệu ''since he was six'' dùng thì hiện tại hoàn thành: ''has studied''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_532_g7alt', '7', 'van_dung_cao', 'published', 'grammar', 'The weather was warm and sunny, ________ we spent the entire afternoon at the beach.', '["A. so","B. but","C. because","D. although"]', 'A', 'Liên từ chỉ kết quả: ''so'' (vì vậy).', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_533_g7alt', '7', 'nhan_biet', 'published', 'grammar', 'If it ________ tomorrow, we will stay indoors and play board games.', '["A. rains","B. will rain","C. rained","D. rain"]', 'A', 'Câu điều kiện loại 1: If + hiện tại đơn ngôi thứ 3 số ít: ''rains''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_534_g7alt', '7', 'thong_hieu', 'published', 'grammar', 'Rewrite test: ''This suitcase is too heavy for me to lift.'' -> ''This suitcase isn''t...''', '["A. light enough for me to lift.","B. heavy enough for me to lift.","C. so light for me to lift.","D. too light for me to lift."]', 'A', 'Biến đổi cấu trúc: too adj to V -> not adj enough to V.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_535_g7alt', '7', 'van_dung', 'published', 'grammar', 'The novel was written ________ a famous young author from Scotland.', '["A. by","B. with","C. at","D. from"]', 'A', 'Câu bị động tác nhân con người: ''written by''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_536_g7alt', '7', 'van_dung_cao', 'published', 'grammar', 'Have you ever ________ to Singapore? -> Yes, twice.', '["A. been","B. gone","C. went","D. be"]', 'A', 'Từng đến đâu rồi trở về: ''Have you ever been to...''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_537_g7alt', '7', 'nhan_biet', 'published', 'vocabulary', 'Can I try this shirt on? -> Yes, the changing rooms are over ________.', '["A. there","B. their","C. they''re","D. here it"]', 'A', 'Phòng thay đồ ở đằng kia: ''over there''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_538_g7alt', '7', 'thong_hieu', 'published', 'grammar', 'She is much ________ at mathematics than her twin brother.', '["A. better","B. good","C. best","D. more good"]', 'A', 'So sánh hơn của good là ''better than''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_539_g7alt', '7', 'van_dung', 'published', 'grammar', 'You ________ touch that hot stove; you will burn your fingers!', '["A. mustn''t","B. needn''t","C. should","D. can"]', 'A', 'Cấm chỉ đoán tai nạn nguy hiểm: ''mustn''t''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_540_g7alt', '7', 'van_dung_cao', 'published', 'vocabulary', 'The doctor advised him to take regular exercise and drink plenty of ________.', '["A. water","B. soda","C. coffee","D. wine"]', 'A', 'Uống nhiều nước lọc tốt cho sức khỏe: ''water''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_541_g7alt', '7', 'nhan_biet', 'published', 'grammar', 'There are thirty students in our class, ________ of whom are girls.', '["A. half","B. two","C. double","D. piece"]', 'A', 'Một nửa trong số đó là học sinh nữ: ''half of whom''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_542_g7alt', '7', 'thong_hieu', 'published', 'grammar', 'Rewrite test: ''I haven''t seen Linda for five months.'' -> ''The last time I saw Linda was...''', '["A. five months ago.","B. since five months.","C. for five months.","D. in five months ago."]', 'A', 'Chuyển từ hiện tại hoàn thành phủ định sang ''The last time... was... ago''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_543_g7alt', '7', 'van_dung', 'published', 'grammar', 'Would you like a cup of green tea? -> ________, I''d prefer a glass of cold water.', '["A. No, thank you","B. Yes, please","C. Sure, why not","D. Of course"]', 'A', 'Từ chối lời mời lịch sự: ''No, thank you''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_544_g7alt', '7', 'van_dung_cao', 'published', 'vocabulary', 'The university library has a vast collection of academic journals ________ to all enrolled students.', '["A. accessible","B. access","C. accessed","D. accessibility"]', 'A', 'Tính từ ''accessible to'' (có thể tiếp cận được đối với).', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_545_g7alt', '7', 'nhan_biet', 'published', 'grammar', 'If you hadn''t reminded me, I ________ forgotten all about the deadline.', '["A. would have","B. will have","C. had","D. would"]', 'A', 'Điều kiện loại 3: If + S + had V3, S + would have + V3.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_546_g7alt', '7', 'thong_hieu', 'published', 'vocabulary', 'The newly appointed manager decided to ________ changes to the shift schedule.', '["A. introduce","B. do","C. take","D. make up"]', 'A', 'Đưa ra/áp dụng các thay đổi: ''introduce changes''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_547_g7alt', '7', 'van_dung', 'published', 'vocabulary', 'Although she was nervous before the presentation, she ________ it off successfully.', '["A. carried","B. made","C. did","D. brought"]', 'A', 'Cụm thành công vượt qua thử thách khó khăn: ''carry it off''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_548_g7alt', '7', 'van_dung_cao', 'published', 'vocabulary', 'The ancient ruins attracted archaeological experts from all ________ the globe.', '["A. over","B. across","C. around","D. through"]', 'A', 'Cụm ''all over the globe'' (khắp toàn cầu).', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_549_g7alt', '7', 'nhan_biet', 'published', 'grammar', 'Rewrite test: ''They are building a modern sports complex near the university.'' -> ''A modern sports complex...''', '["A. is being built near the university.","B. was built near the university.","C. is built near the university.","D. has built near the university."]', 'A', 'Bị động thì hiện tại tiếp diễn: ''is being built''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_550_g7alt', '7', 'thong_hieu', 'published', 'vocabulary', 'We should make sure to set off early to avoid getting stuck in the morning rush ________.', '["A. hour","B. time","C. period","D. minute"]', 'A', 'Giờ cao điểm giao thông: ''rush hour''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_551_g7alt', '7', 'van_dung', 'published', 'grammar', 'The teacher encouraged her pupils ________ actively in group discussions.', '["A. to participate","B. participate","C. participating","D. participated"]', 'A', 'Cấu trúc encourage someone to V: ''to participate''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_552_g7alt', '7', 'van_dung_cao', 'published', 'grammar', 'Rewrite test: ''I suggest taking a taxi because it''s pouring outside.'' -> ''Why don''t we...''', '["A. take a taxi because it''s pouring outside?","B. taking a taxi because it''s pouring outside?","C. to take a taxi because it''s pouring outside?","D. took a taxi because it''s pouring outside?"]', 'A', 'Biến đổi cấu trúc gợi ý: suggest V-ing -> Why don''t we + V nguyên mẫu?', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_553_g7alt', '7', 'nhan_biet', 'published', 'vocabulary', 'Unless emergency repairs are carried ________ promptly, the bridge may collapse.', '["A. out","B. on","C. off","D. in"]', 'A', 'Tiến hành thực hiện sửa chữa: ''carried out''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_554_g7alt', '7', 'thong_hieu', 'published', 'grammar', 'The committee consists ________ ten distinguished professors in education.', '["A. of","B. in","C. with","D. for"]', 'A', 'Bao gồm, gồm có: ''consist of''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_555_g7alt', '7', 'van_dung', 'published', 'grammar', 'He apologized to his colleagues ________ having missed the quarterly briefing.', '["A. for","B. about","C. with","D. on"]', 'A', 'Xin lỗi vì điều gì: ''apologize for + V-ing''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_556_g7alt', '7', 'van_dung_cao', 'published', 'vocabulary', 'The novel was so thrilling that she finished reading it in a single ________.', '["A. sitting","B. standing","C. lying","D. staying"]', 'A', 'Đọc liền một mạch: ''in a single sitting''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_557_g7alt', '7', 'nhan_biet', 'published', 'grammar', 'Rewrite test: ''Nobody in my class speaks Spanish better than Maria.'' -> ''Maria speaks Spanish...''', '["A. the best in my class.","B. better than anyone in my class.","C. as well as nobody in my class.","D. good in my class."]', 'A', 'So sánh nhất chuyển từ so sánh hơn phủ định.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_558_g7alt', '7', 'thong_hieu', 'published', 'grammar', 'I really appreciate your helping hand during the school festival! -> ________', '["A. It was my pleasure, anytime!","B. No thanks.","C. Yes, please.","D. Never mind."]', 'A', 'Đáp lại lời cảm ơn một cách thân thiện, nhiệt tình.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_559_g7alt', '7', 'van_dung', 'published', 'reading', 'Passage statement: ''Solar installations expanded by 45% in 2024.'' Question: Solar energy saw unprecedented growth recently. -> ________', '["A. TRUE","B. FALSE","C. NOT GIVEN","D. NONE"]', 'A', 'Đoạn văn xác nhận mức tăng 45% chứng minh sự phát triển chưa từng có -> TRUE.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_560_g7alt', '7', 'van_dung_cao', 'published', 'reading', 'Passage statement: ''The researchers examined 50 coral species.'' Question: All coral species will recover within a decade. -> ________', '["A. NOT GIVEN","B. TRUE","C. FALSE","D. NONE"]', 'A', 'Bài viết không hề khẳng định toàn bộ loài san hô sẽ phục hồi trong 10 năm -> NOT GIVEN.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_561_g7alt', '7', 'nhan_biet', 'published', 'vocabulary', 'The policy was introduced with the overarching aim of ________ socio-economic disparities.', '["A. mitigating","B. increasing","C. aggravating","D. celebrating"]', 'A', 'Giảm thiểu, làm nhẹ bớt sự chênh lệch kinh tế xã hội: ''mitigating disparities''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_562_g7alt', '7', 'thong_hieu', 'published', 'vocabulary', 'The empirical findings corroborate the initial hypothesis. -> ''Corroborate'' is CLOSEST in meaning to: ________', '["A. confirm","B. contradict","C. dismiss","D. reject"]', 'A', '''corroborate'' đồng nghĩa với ''confirm'' (chứng thực, củng cố tính đúng đắn).', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_563_g7alt', '7', 'van_dung', 'published', 'vocabulary', 'Industrial effluent discharged into marine ecosystems poses a ________ threat to aquatic organisms.', '["A. grave","B. minor","C. pleasant","D. gentle"]', 'A', 'Mối đe dọa nghiêm trọng: ''grave threat''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_564_g7alt', '7', 'van_dung_cao', 'published', 'vocabulary', 'Governments must impose stringent regulations to curb the rampant ________ of natural resources.', '["A. depletion","B. creation","C. generation","D. production"]', 'A', 'Sự suy kiệt cạn kiệt tài nguyên thiên nhiên: ''depletion''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_565_g7alt', '7', 'nhan_biet', 'published', 'grammar', 'The sudden influx of tourists placed an unsustainable strain ________ the island''s fragile infrastructure.', '["A. on","B. in","C. at","D. with"]', 'A', 'Gây áp lực nặng nề lên điều gì: ''place a strain on''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_566_g7alt', '7', 'thong_hieu', 'published', 'grammar', 'Not only ________ carbon emissions, but electric vehicles also significantly reduce noise pollution.', '["A. do they diminish","B. they diminish","C. they do diminish","D. did they diminish"]', 'A', 'Đảo ngữ với ''Not only'': trợ động từ ''do'' + they + V nguyên mẫu.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_567_g7alt', '7', 'van_dung', 'published', 'reading', 'The author''s tone throughout the academic treatise can best be described as ________.', '["A. objective and analytical","B. sarcastic and cynical","C. emotional and biassed","D. indifferent"]', 'A', 'Văn phong học thuật chuẩn mực luôn khách quan và mang tính phân tích: ''objective and analytical''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_568_g7alt', '7', 'van_dung_cao', 'published', 'vocabulary', 'Urbanisation has precipitated an unprecedented surge in demand for affordable ________.', '["A. housing","B. house","C. housed","D. houser"]', 'A', 'Nhà ở giá cả phải chăng: ''affordable housing''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_569_g7alt', '7', 'nhan_biet', 'published', 'vocabulary', 'The new vaccine demonstrated exceptional efficacy in ________ clinical trials.', '["A. rigorous","B. careless","C. superficial","D. randomless"]', 'A', 'Các thử nghiệm lâm sàng nghiêm ngặt chặt chẽ: ''rigorous clinical trials''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_570_g7alt', '7', 'thong_hieu', 'published', 'grammar', 'Had the regulatory authorities acted with greater urgency, the ecological catastrophe ________ averted.', '["A. might have been","B. might be","C. was","D. will be"]', 'A', 'Đảo ngữ câu điều kiện loại 3 dạng bị động: ''might have been averted''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_571_g7alt', '7', 'van_dung', 'published', 'vocabulary', 'Academic writing requires students to synthesise diverse perspectives and avoid ________ reasoning.', '["A. fallacious","B. logical","C. sound","D. coherent"]', 'A', 'Lập luận ngụy biện, sai lệch: ''fallacious reasoning''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_572_g7alt', '7', 'van_dung_cao', 'published', 'vocabulary', 'The ubiquitous presence of microplastics in drinking water warrants urgent international ________.', '["A. intervention","B. neglect","C. disregard","D. hesitation"]', 'A', 'Đòi hỏi sự can thiệp cấp thiết quốc tế: ''international intervention''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_cat_573_g7alt', '7', 'nhan_biet', 'published', 'vocabulary', 'To recapitulate, addressing climate change necessitates a paradigm ________ in global energy consumption.', '["A. shift","B. move","C. turn","D. step"]', 'A', 'Sự thay đổi căn bản trong nhận thức và phương thức (bước chuyển hình thái): ''paradigm shift''.', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_sup_g7_phonics_1_g7alt', '7', 'nhan_biet', 'published', 'phonics', 'Choose the word with different pronunciation of the underlined part: h<u>ea</u>d, br<u>ea</u>d, cl<u>ea</u>n, h<u>ea</u>vy', '["A. head","B. bread","C. clean","D. heavy"]', 'C', 'clean has /i:/ while others have /e/', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_sup_g7_phonics_2_g7alt', '7', 'thong_hieu', 'published', 'phonics', 'Choose the word whose underlined part is pronounced differently: look<u>ed</u>, watch<u>ed</u>, carri<u>ed</u>, stopp<u>ed</u>', '["A. looked","B. watched","C. carried","D. stopped"]', 'C', 'carried has /d/ while others have /t/', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_sup_g7_phonics_3_g7alt', '7', 'van_dung', 'published', 'phonics', 'Choose the word whose stress pattern is different from the others: intend, decide, happen, agree', '["A. intend","B. decide","C. happen","D. agree"]', 'C', 'happen has stress on 1st syllable, others on 2nd', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_sup_g7_phonics_4_g7alt', '7', 'van_dung_cao', 'published', 'phonics', 'Choose the word whose stress is placed differently: economic, Vietnamese, celebration, category', '["A. economic","B. Vietnamese","C. celebration","D. category"]', 'D', 'category has stress on 1st syllable', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_sup_g7_phonics_5_g7alt', '7', 'nhan_biet', 'published', 'phonics', 'Choose the word with different pronunciation of the underlined part: h<u>ea</u>d, br<u>ea</u>d, cl<u>ea</u>n, h<u>ea</u>vy', '["A. head","B. bread","C. clean","D. heavy"]', 'C', 'clean has /i:/ while others have /e/', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_sup_g7_phonics_6_g7alt', '7', 'thong_hieu', 'published', 'phonics', 'Choose the word whose underlined part is pronounced differently: look<u>ed</u>, watch<u>ed</u>, carri<u>ed</u>, stopp<u>ed</u>', '["A. looked","B. watched","C. carried","D. stopped"]', 'C', 'carried has /d/ while others have /t/', NULL);
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_sup_g7_reading_1_g7alt', '7', 'nhan_biet', 'published', 'reading', 'According to the passage, why do students need to practice reading every day?', '["A. To improve vocabulary and reading speed","B. To pass exams only","C. Because teachers force them","D. To play more games"]', 'A', 'Daily reading enhances both vocabulary comprehension and processing speed.', 'Reading is one of the most effective habits to acquire a second language naturally. When learners expose themselves to various texts daily, they encounter recurring patterns and rich contexts that solidify long-term retention.');
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_sup_g7_reading_2_g7alt', '7', 'thong_hieu', 'published', 'reading', 'What is the main topic of the reading text?', '["A. Modern communication technologies","B. The importance of daily reading habits","C. History of English grammar","D. Tips for writing essays"]', 'B', 'The central theme focuses on the role of consistent reading habits in language mastery.', 'Reading is one of the most effective habits to acquire a second language naturally. When learners expose themselves to various texts daily, they encounter recurring patterns and rich contexts that solidify long-term retention.');
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_sup_g7_reading_3_g7alt', '7', 'van_dung', 'published', 'reading', 'The word "solidify" in the passage is closest in meaning to:', '["A. weaken","B. strengthen","C. eliminate","D. doubt"]', 'B', 'Solidify means to make something stronger and more definite.', 'Reading is one of the most effective habits to acquire a second language naturally. When learners expose themselves to various texts daily, they encounter recurring patterns and rich contexts that solidify long-term retention.');
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_sup_g7_reading_4_g7alt', '7', 'van_dung_cao', 'published', 'reading', 'Which of the following is NOT true according to the passage?', '["A. Daily reading expands vocabulary","B. Texts provide rich contexts","C. Reading makes learners forget patterns","D. Reading supports long-term retention"]', 'C', 'The passage explicitly states reading solidifies patterns, rather than forgetting them.', 'Reading is one of the most effective habits to acquire a second language naturally. When learners expose themselves to various texts daily, they encounter recurring patterns and rich contexts that solidify long-term retention.');
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_sup_g7_reading_5_g7alt', '7', 'nhan_biet', 'published', 'reading', 'According to the passage, why do students need to practice reading every day?', '["A. To improve vocabulary and reading speed","B. To pass exams only","C. Because teachers force them","D. To play more games"]', 'A', 'Daily reading enhances both vocabulary comprehension and processing speed.', 'Reading is one of the most effective habits to acquire a second language naturally. When learners expose themselves to various texts daily, they encounter recurring patterns and rich contexts that solidify long-term retention.');
INSERT OR IGNORE INTO question_bank (id, grade_level, cognitive_level, status, skill_category, question_text, options_json, correct_option_id, explanation, reading_passage) VALUES ('qb_sup_g7_reading_6_g7alt', '7', 'thong_hieu', 'published', 'reading', 'What is the main topic of the reading text?', '["A. Modern communication technologies","B. The importance of daily reading habits","C. History of English grammar","D. Tips for writing essays"]', 'B', 'The central theme focuses on the role of consistent reading habits in language mastery.', 'Reading is one of the most effective habits to acquire a second language naturally. When learners expose themselves to various texts daily, they encounter recurring patterns and rich contexts that solidify long-term retention.');